package com.farm.demo.view;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;

public class AlertManagementPanel extends JPanel {

    // ── Theme colours ──
    private static final Color BG_DARK      = new Color(0x0A, 0x16, 0x28);
    private static final Color CARD_BG      = new Color(0x0D, 0x21, 0x37);
    private static final Color CARD_BG_ALT  = new Color(0x11, 0x22, 0x44);
    private static final Color ACCENT_BLUE  = new Color(0x15, 0x65, 0xC0);
    private static final Color ACCENT_GREEN = new Color(0x00, 0xE6, 0x76);
    private static final Color ACCENT_AMBER = new Color(0xFF, 0xC1, 0x07);
    private static final Color ACCENT_RED   = new Color(0xF4, 0x43, 0x36);
    private static final Color TEXT_WHITE    = Color.WHITE;
    private static final Color TEXT_GRAY     = new Color(0x99, 0xAA, 0xBB);
    private static final Color ROW_CRIT     = new Color(0x2E, 0x0F, 0x0A);
    private static final Color ROW_WARN     = new Color(0x2E, 0x25, 0x0A);

    private static final DateTimeFormatter DISPLAY_FMT =
            DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss");
    private static final DateTimeFormatter PARSE_FMT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm");

    private final Farm farm;

    // Stats labels
    private JLabel critLabel, warnLabel, totalLabel;

    // Active alerts table
    private DefaultTableModel activeModel;
    private JTable activeTable;

    // History table
    private DefaultTableModel histModel;
    private JTable histTable;
    private JComboBox<String> hZoneCombo, hSeverityCombo;
    private JTextField hSensorField, hStartField, hEndField;

    // Overview labels
    private JLabel ovCritical, ovWarning, ovNormal;
    private JPanel ovCritBar, ovWarnBar, ovNormBar;

    public AlertManagementPanel(Farm farm) {
        this.farm = farm;
        setLayout(new BorderLayout(10, 10));
        setBackground(BG_DARK);
        setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        // North: stats + overview
        JPanel northPanel = new JPanel(new BorderLayout(10, 0));
        northPanel.setOpaque(false);
        northPanel.add(buildStatsBar(), BorderLayout.CENTER);
        northPanel.add(buildOverviewPanel(), BorderLayout.EAST);
        add(northPanel, BorderLayout.NORTH);

        // Center: tabbed pane with Active & History
        JTabbedPane tabs = new JTabbedPane();
        tabs.setBackground(CARD_BG);
        tabs.setForeground(TEXT_WHITE);
        tabs.setFont(new Font("SansSerif", Font.BOLD, 12));

        // Active tab
        JPanel activePanel = new JPanel(new BorderLayout(0, 8));
        activePanel.setBackground(BG_DARK);
        activePanel.add(buildActiveTable(), BorderLayout.CENTER);
        activePanel.add(buildActiveActionBar(), BorderLayout.SOUTH);
        tabs.addTab("Active Alerts", activePanel);

        // History tab
        tabs.addTab("History", buildHistoryPanel());

        add(tabs, BorderLayout.CENTER);

        refreshAll();
    }

    // ═══════════════════════════ A) STATS BAR ═══════════════════════════

    private JPanel buildStatsBar() {
        JPanel bar = new JPanel(new GridLayout(1, 3, 12, 0));
        bar.setOpaque(false);
        bar.setPreferredSize(new Dimension(0, 80));

        critLabel  = new JLabel("0", SwingConstants.CENTER);
        warnLabel  = new JLabel("0", SwingConstants.CENTER);
        totalLabel = new JLabel("0", SwingConstants.CENTER);

        bar.add(makeStatCard(critLabel,  "Critical Alerts", new Color(0x3A, 0x0A, 0x0A)));
        bar.add(makeStatCard(warnLabel,  "Warning Alerts",  new Color(0x3A, 0x2D, 0x00)));
        bar.add(makeStatCard(totalLabel, "Total Active",    CARD_BG));
        return bar;
    }

    private RoundedPanel makeStatCard(JLabel numLabel, String subtitle, Color bg) {
        RoundedPanel card = new RoundedPanel(bg, 16);
        card.setLayout(new BorderLayout());
        numLabel.setFont(new Font("SansSerif", Font.BOLD, 28));
        numLabel.setForeground(TEXT_WHITE);
        JLabel sub = new JLabel(subtitle, SwingConstants.CENTER);
        sub.setFont(new Font("SansSerif", Font.PLAIN, 12));
        sub.setForeground(TEXT_GRAY);
        card.add(numLabel, BorderLayout.CENTER);
        card.add(sub, BorderLayout.SOUTH);
        card.setBorder(BorderFactory.createEmptyBorder(8, 10, 10, 10));
        return card;
    }

    // ═══════════════════════════ E) OVERVIEW PANEL ═══════════════════════════

    private JPanel buildOverviewPanel() {
        RoundedPanel panel = new RoundedPanel(CARD_BG, 16);
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBorder(BorderFactory.createEmptyBorder(10, 14, 10, 14));
        panel.setPreferredSize(new Dimension(220, 80));

        JLabel title = new JLabel("Alerts Overview");
        title.setFont(new Font("SansSerif", Font.BOLD, 13));
        title.setForeground(TEXT_WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.add(title);
        panel.add(Box.createVerticalStrut(6));

        ovCritical = new JLabel("CRITICAL: 0");
        ovWarning  = new JLabel("WARNING: 0");
        ovNormal   = new JLabel("NORMAL: 0");

        ovCritBar = makeOverviewRow(ACCENT_RED,   ovCritical);
        ovWarnBar = makeOverviewRow(ACCENT_AMBER, ovWarning);
        ovNormBar = makeOverviewRow(ACCENT_GREEN, ovNormal);

        panel.add(ovCritBar);
        panel.add(Box.createVerticalStrut(4));
        panel.add(ovWarnBar);
        panel.add(Box.createVerticalStrut(4));
        panel.add(ovNormBar);

        return panel;
    }

    private JPanel makeOverviewRow(Color color, JLabel label) {
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel colorBlock = new JPanel();
        colorBlock.setBackground(color);
        colorBlock.setPreferredSize(new Dimension(12, 16));

        label.setFont(new Font("SansSerif", Font.BOLD, 11));
        label.setForeground(TEXT_WHITE);

        row.add(colorBlock, BorderLayout.WEST);
        row.add(label, BorderLayout.CENTER);
        return row;
    }

    // ═══════════════════════════ B) ACTIVE TABLE ═══════════════════════════

    private JPanel buildActiveTable() {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(BG_DARK);

        String[] cols = {"ID", "Severity", "Sensor", "Zone", "Value",
                "Timestamp", "Message", "Status"};
        activeModel = new DefaultTableModel(cols, 0) {
            @Override public boolean isCellEditable(int r, int c) { return false; }
        };
        activeTable = new JTable(activeModel);
        styleAlertTable(activeTable);
        activeTable.getColumnModel().getColumn(1).setCellRenderer(new SeverityBadgeRenderer());

        JScrollPane sp = new JScrollPane(activeTable);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        panel.add(sp, BorderLayout.CENTER);
        return panel;
    }

    // ═══════════════════════════ C) ACTIVE ACTION BAR ═══════════════════════════

    private JPanel buildActiveActionBar() {
        JPanel bar = new JPanel(new FlowLayout(FlowLayout.CENTER, 12, 6));
        bar.setBackground(CARD_BG);
        bar.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

        bar.add(makeBtn("Acknowledge", ACCENT_GREEN, e -> {
            int row = activeTable.getSelectedRow();
            if (row < 0) { warn("Please select an alert first."); return; }
            int id = (int) activeModel.getValueAt(row, 0);
            String msg = farm.acknowledgeAlert(id);
            JOptionPane.showMessageDialog(this, msg);
            refreshAll();
        }));

        bar.add(makeBtn("Dismiss", ACCENT_RED, e -> {
            int row = activeTable.getSelectedRow();
            if (row < 0) { warn("Please select an alert first."); return; }
            int id = (int) activeModel.getValueAt(row, 0);
            String msg = farm.dismissAlert(id);
            JOptionPane.showMessageDialog(this, msg);
            refreshAll();
        }));

        bar.add(makeBtn("Refresh", ACCENT_BLUE, e -> refreshAll()));

        return bar;
    }

    // ═══════════════════════════ D) HISTORY PANEL ═══════════════════════════

    private JPanel buildHistoryPanel() {
        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.setBackground(BG_DARK);
        panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        // Filter bar
        JPanel filters = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 4));
        filters.setOpaque(false);

        hZoneCombo = new JComboBox<>();
        hZoneCombo.addItem("All");
        for (Zone z : farm.getZones()) hZoneCombo.addItem(z.getCode());
        styleCombo(hZoneCombo);
        filters.add(darkLabel("Zone:")); filters.add(hZoneCombo);

        hSensorField = darkField("");
        hSensorField.setColumns(8);
        filters.add(darkLabel("Sensor:")); filters.add(hSensorField);

        hSeverityCombo = new JComboBox<>(new String[]{"All", "WARNING", "CRITICAL"});
        styleCombo(hSeverityCombo);
        filters.add(darkLabel("Severity:")); filters.add(hSeverityCombo);

        hStartField = darkField("");
        hStartField.setColumns(12);
        hStartField.setToolTipText("yyyy-MM-ddTHH:mm");
        filters.add(darkLabel("Start:")); filters.add(hStartField);

        hEndField = darkField("");
        hEndField.setColumns(12);
        hEndField.setToolTipText("yyyy-MM-ddTHH:mm");
        filters.add(darkLabel("End:")); filters.add(hEndField);

        filters.add(makeBtn("Search", ACCENT_BLUE, e -> searchHistory()));

        panel.add(filters, BorderLayout.NORTH);

        // History table
        String[] cols = {"ID", "Severity", "Sensor", "Zone", "Value",
                "Timestamp", "Message", "Status"};
        histModel = new DefaultTableModel(cols, 0) {
            @Override public boolean isCellEditable(int r, int c) { return false; }
        };
        histTable = new JTable(histModel);
        styleAlertTable(histTable);
        histTable.getColumnModel().getColumn(1).setCellRenderer(new SeverityBadgeRenderer());

        JScrollPane sp = new JScrollPane(histTable);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        panel.add(sp, BorderLayout.CENTER);

        return panel;
    }

    private void searchHistory() {
        String zone = (String) hZoneCombo.getSelectedItem();
        String zoneCode = "All".equals(zone) ? null : zone;

        String sensor = hSensorField.getText().trim();
        String sensorCode = sensor.isEmpty() ? null : sensor;

        String sev = (String) hSeverityCombo.getSelectedItem();
        SeverityLevel level = null;
        if ("WARNING".equals(sev))  level = SeverityLevel.WARNING;
        if ("CRITICAL".equals(sev)) level = SeverityLevel.CRITICAL;

        LocalDateTime start = parseDate(hStartField.getText().trim());
        LocalDateTime end   = parseDate(hEndField.getText().trim());

        List<Alert> results = farm.getAlertHistory(zoneCode, sensorCode, level, start, end);
        populateAlertTable(histModel, results);
    }

    // ═══════════════════════════ REFRESH ═══════════════════════════

    public void refreshAll() {
        refreshActiveTable();
        refreshStats();
        refreshOverview();
    }

    private void refreshActiveTable() {
        List<Alert> active = AlertManager.getActiveAlertsSortedBySeverity();
        populateAlertTable(activeModel, active);
    }

    private void populateAlertTable(DefaultTableModel model, List<Alert> alerts) {
        model.setRowCount(0);
        for (Alert a : alerts) {
            model.addRow(new Object[]{
                    a.getAlertId(),
                    a.getSeverityLevel().name(),
                    a.getSensorUniqueCode(),
                    a.getZoneId(),
                    String.format("%.2f", a.getReadingValue()),
                    a.getAlertTimestamp().format(DISPLAY_FMT),
                    a.getMessage(),
                    a.isAcknowledged() ? "Acknowledged" : "Pending"
            });
        }
    }

    private void refreshStats() {
        List<Alert> active = AlertManager.getActiveAlertsSortedBySeverity();
        long crit = active.stream().filter(a -> a.getSeverityLevel() == SeverityLevel.CRITICAL).count();
        long warn = active.stream().filter(a -> a.getSeverityLevel() == SeverityLevel.WARNING).count();
        critLabel.setText(String.valueOf(crit));
        warnLabel.setText(String.valueOf(warn));
        totalLabel.setText(String.valueOf(active.size()));
    }

    private void refreshOverview() {
        long crit = AlertManager.getActiveAlertsSortedBySeverity().stream()
                .filter(a -> a.getSeverityLevel() == SeverityLevel.CRITICAL).count();
        long warn = AlertManager.getActiveAlertsSortedBySeverity().stream()
                .filter(a -> a.getSeverityLevel() == SeverityLevel.WARNING).count();
        long norm = AlertManager.getActiveAlertsSortedBySeverity().stream()
                .filter(a -> a.getSeverityLevel() == SeverityLevel.NORMAL).count();
        ovCritical.setText("CRITICAL: " + crit + " alerts");
        ovWarning.setText("WARNING: " + warn + " alerts");
        ovNormal.setText("NORMAL: " + norm + " alerts");
    }

    // ═══════════════════════════ TABLE STYLING ═══════════════════════════

    private void styleAlertTable(JTable table) {
        table.setBackground(CARD_BG);
        table.setForeground(TEXT_WHITE);
        table.setGridColor(new Color(0x1A, 0x33, 0x50));
        table.setRowHeight(32);
        table.setFont(new Font("SansSerif", Font.PLAIN, 12));
        table.setSelectionBackground(ACCENT_BLUE);
        table.setSelectionForeground(TEXT_WHITE);
        table.setShowGrid(true);
        table.setIntercellSpacing(new Dimension(1, 1));

        JTableHeader header = table.getTableHeader();
        header.setBackground(ACCENT_BLUE);
        header.setForeground(TEXT_WHITE);
        header.setFont(new Font("SansSerif", Font.BOLD, 12));
        header.setReorderingAllowed(false);

        // Custom row colouring for severity tint
        DefaultTableModel model = (DefaultTableModel) table.getModel();
        table.setDefaultRenderer(Object.class, new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable t, Object v,
                                                           boolean sel, boolean foc, int r, int c) {
                Component comp = super.getTableCellRendererComponent(t, v, sel, foc, r, c);
                if (!sel) {
                    String severity = (String) t.getModel().getValueAt(r, 1);
                    if ("CRITICAL".equals(severity)) {
                        comp.setBackground(ROW_CRIT);
                    } else if ("WARNING".equals(severity)) {
                        comp.setBackground(ROW_WARN);
                    } else {
                        comp.setBackground(r % 2 == 0 ? CARD_BG : CARD_BG_ALT);
                    }
                    comp.setForeground(TEXT_WHITE);
                }
                return comp;
            }
        });
    }

    // ═══════════════════════════ HELPERS ═══════════════════════════

    private JButton makeBtn(String text, Color bg, ActionListener action) {
        JButton btn = new JButton(text);
        btn.setBackground(bg);
        btn.setForeground(TEXT_WHITE);
        btn.setFont(new Font("SansSerif", Font.BOLD, 12));
        btn.setFocusPainted(false);
        btn.setBorder(BorderFactory.createEmptyBorder(8, 18, 8, 18));
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { btn.setBackground(bg.brighter()); }
            @Override public void mouseExited(MouseEvent e)  { btn.setBackground(bg); }
        });
        if (action != null) btn.addActionListener(action);
        return btn;
    }

    private JLabel darkLabel(String text) {
        JLabel l = new JLabel(text);
        l.setForeground(TEXT_GRAY);
        l.setFont(new Font("SansSerif", Font.PLAIN, 12));
        return l;
    }

    private JTextField darkField(String text) {
        JTextField f = new JTextField(text);
        f.setBackground(CARD_BG_ALT);
        f.setForeground(TEXT_WHITE);
        f.setCaretColor(TEXT_WHITE);
        f.setFont(new Font("SansSerif", Font.PLAIN, 12));
        f.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ACCENT_BLUE, 1),
                BorderFactory.createEmptyBorder(4, 6, 4, 6)));
        return f;
    }

    private void styleCombo(JComboBox<String> combo) {
        combo.setBackground(CARD_BG_ALT);
        combo.setForeground(TEXT_WHITE);
        combo.setFont(new Font("SansSerif", Font.PLAIN, 12));
    }

    private LocalDateTime parseDate(String text) {
        if (text == null || text.isEmpty()) return null;
        try {
            return LocalDateTime.parse(text, PARSE_FMT);
        } catch (Exception e) {
            return null;
        }
    }

    private void warn(String msg) {
        JOptionPane.showMessageDialog(this, msg, "Warning", JOptionPane.WARNING_MESSAGE);
    }
}

package com.farm.demo.view;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.*;
import com.farm.demo.model.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;

public class AlertManagementPanel extends JPanel {

    // ── Theme colours ──
    private static final Color BG_DARK      = new Color(0x0A, 0x16, 0x28);
    private static final Color CARD_BG      = new Color(0x0D, 0x21, 0x37);
    private static final Color CARD_BG_ALT  = new Color(0x11, 0x22, 0x44);
    private static final Color ACCENT_BLUE  = new Color(0x15, 0x65, 0xC0);
    private static final Color ACCENT_GREEN = new Color(0x00, 0xE6, 0x76);
    private static final Color ACCENT_AMBER = new Color(0xFF, 0xC1, 0x07);
    private static final Color ACCENT_RED   = new Color(0xF4, 0x43, 0x36);
    private static final Color TEXT_WHITE    = Color.WHITE;
    private static final Color TEXT_GRAY     = new Color(0x99, 0xAA, 0xBB);
    private static final Color ROW_CRIT     = new Color(0x2E, 0x0F, 0x0A);
    private static final Color ROW_WARN     = new Color(0x2E, 0x25, 0x0A);

    private static final DateTimeFormatter DISPLAY_FMT =
            DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss");
    private static final DateTimeFormatter PARSE_FMT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm");

    private final Farm farm;

    // Stats labels
    private JLabel critLabel, warnLabel, totalLabel;

    // Active alerts table
    private DefaultTableModel activeModel;
    private JTable activeTable;

    // History table
    private DefaultTableModel histModel;
    private JTable histTable;
    private JComboBox<String> hZoneCombo, hSeverityCombo;
    private JTextField hSensorField, hStartField, hEndField;

    // Overview labels
    private JLabel ovCritical, ovWarning, ovNormal;
    private JPanel ovCritBar, ovWarnBar, ovNormBar;

    public AlertManagementPanel(Farm farm) {
        this.farm = farm;
        setLayout(new BorderLayout(10, 10));
        setBackground(BG_DARK);
        setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        // North: stats + overview
        JPanel northPanel = new JPanel(new BorderLayout(10, 0));
        northPanel.setOpaque(false);
        northPanel.add(buildStatsBar(), BorderLayout.CENTER);
        northPanel.add(buildOverviewPanel(), BorderLayout.EAST);
        add(northPanel, BorderLayout.NORTH);

        // Center: tabbed pane with Active & History
        JTabbedPane tabs = new JTabbedPane();
        tabs.setBackground(CARD_BG);
        tabs.setForeground(TEXT_WHITE);
        tabs.setFont(new Font("SansSerif", Font.BOLD, 12));

        // Active tab
        JPanel activePanel = new JPanel(new BorderLayout(0, 8));
        activePanel.setBackground(BG_DARK);
        activePanel.add(buildActiveTable(), BorderLayout.CENTER);
        activePanel.add(buildActiveActionBar(), BorderLayout.SOUTH);
        tabs.addTab("Active Alerts", activePanel);

        // History tab
        tabs.addTab("History", buildHistoryPanel());

        add(tabs, BorderLayout.CENTER);

        refreshAll();
    }

    // ═══════════════════════════ A) STATS BAR ═══════════════════════════

    private JPanel buildStatsBar() {
        JPanel bar = new JPanel(new GridLayout(1, 3, 12, 0));
        bar.setOpaque(false);
        bar.setPreferredSize(new Dimension(0, 80));

        critLabel  = new JLabel("0", SwingConstants.CENTER);
        warnLabel  = new JLabel("0", SwingConstants.CENTER);
        totalLabel = new JLabel("0", SwingConstants.CENTER);

        bar.add(makeStatCard(critLabel,  "Critical Alerts", new Color(0x3A, 0x0A, 0x0A)));
        bar.add(makeStatCard(warnLabel,  "Warning Alerts",  new Color(0x3A, 0x2D, 0x00)));
        bar.add(makeStatCard(totalLabel, "Total Active",    CARD_BG));
        return bar;
    }

    private RoundedPanel makeStatCard(JLabel numLabel, String subtitle, Color bg) {
        RoundedPanel card = new RoundedPanel(bg, 16);
        card.setLayout(new BorderLayout());
        numLabel.setFont(new Font("SansSerif", Font.BOLD, 28));
        numLabel.setForeground(TEXT_WHITE);
        JLabel sub = new JLabel(subtitle, SwingConstants.CENTER);
        sub.setFont(new Font("SansSerif", Font.PLAIN, 12));
        sub.setForeground(TEXT_GRAY);
        card.add(numLabel, BorderLayout.CENTER);
        card.add(sub, BorderLayout.SOUTH);
        card.setBorder(BorderFactory.createEmptyBorder(8, 10, 10, 10));
        return card;
    }

    // ═══════════════════════════ E) OVERVIEW PANEL ═══════════════════════════

    private JPanel buildOverviewPanel() {
        RoundedPanel panel = new RoundedPanel(CARD_BG, 16);
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBorder(BorderFactory.createEmptyBorder(10, 14, 10, 14));
        panel.setPreferredSize(new Dimension(220, 80));

        JLabel title = new JLabel("Alerts Overview");
        title.setFont(new Font("SansSerif", Font.BOLD, 13));
        title.setForeground(TEXT_WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.add(title);
        panel.add(Box.createVerticalStrut(6));

        ovCritical = new JLabel("CRITICAL: 0");
        ovWarning  = new JLabel("WARNING: 0");
        ovNormal   = new JLabel("NORMAL: 0");

        ovCritBar = makeOverviewRow(ACCENT_RED,   ovCritical);
        ovWarnBar = makeOverviewRow(ACCENT_AMBER, ovWarning);
        ovNormBar = makeOverviewRow(ACCENT_GREEN, ovNormal);

        panel.add(ovCritBar);
        panel.add(Box.createVerticalStrut(4));
        panel.add(ovWarnBar);
        panel.add(Box.createVerticalStrut(4));
        panel.add(ovNormBar);

        return panel;
    }

    private JPanel makeOverviewRow(Color color, JLabel label) {
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel colorBlock = new JPanel();
        colorBlock.setBackground(color);
        colorBlock.setPreferredSize(new Dimension(12, 16));

        label.setFont(new Font("SansSerif", Font.BOLD, 11));
        label.setForeground(TEXT_WHITE);

        row.add(colorBlock, BorderLayout.WEST);
        row.add(label, BorderLayout.CENTER);
        return row;
    }

    // ═══════════════════════════ B) ACTIVE TABLE ═══════════════════════════

    private JPanel buildActiveTable() {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(BG_DARK);

        String[] cols = {"ID", "Severity", "Sensor", "Zone", "Value",
                "Timestamp", "Message", "Status"};
        activeModel = new DefaultTableModel(cols, 0) {
            @Override public boolean isCellEditable(int r, int c) { return false; }
        };
        activeTable = new JTable(activeModel);
        styleAlertTable(activeTable);
        activeTable.getColumnModel().getColumn(1).setCellRenderer(new SeverityBadgeRenderer());

        JScrollPane sp = new JScrollPane(activeTable);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        panel.add(sp, BorderLayout.CENTER);
        return panel;
    }

    // ═══════════════════════════ C) ACTIVE ACTION BAR ═══════════════════════════

    private JPanel buildActiveActionBar() {
        JPanel bar = new JPanel(new FlowLayout(FlowLayout.CENTER, 12, 6));
        bar.setBackground(CARD_BG);
        bar.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

        bar.add(makeBtn("Acknowledge", ACCENT_GREEN, e -> {
            int row = activeTable.getSelectedRow();
            if (row < 0) { warn("Please select an alert first."); return; }
            int id = (int) activeModel.getValueAt(row, 0);
            String msg = farm.acknowledgeAlert(id);
            JOptionPane.showMessageDialog(this, msg);
            refreshAll();
        }));

        bar.add(makeBtn("Dismiss", ACCENT_RED, e -> {
            int row = activeTable.getSelectedRow();
            if (row < 0) { warn("Please select an alert first."); return; }
            int id = (int) activeModel.getValueAt(row, 0);
            String msg = farm.dismissAlert(id);
            JOptionPane.showMessageDialog(this, msg);
            refreshAll();
        }));

        bar.add(makeBtn("Refresh", ACCENT_BLUE, e -> refreshAll()));

        return bar;
    }

    // ═══════════════════════════ D) HISTORY PANEL ═══════════════════════════

    private JPanel buildHistoryPanel() {
        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.setBackground(BG_DARK);
        panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        // Filter bar
        JPanel filters = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 4));
        filters.setOpaque(false);

        hZoneCombo = new JComboBox<>();
        hZoneCombo.addItem("All");
        for (Zone z : farm.getZones()) hZoneCombo.addItem(z.getCode());
        styleCombo(hZoneCombo);
        filters.add(darkLabel("Zone:")); filters.add(hZoneCombo);

        hSensorField = darkField("");
        hSensorField.setColumns(8);
        filters.add(darkLabel("Sensor:")); filters.add(hSensorField);

        hSeverityCombo = new JComboBox<>(new String[]{"All", "WARNING", "CRITICAL"});
        styleCombo(hSeverityCombo);
        filters.add(darkLabel("Severity:")); filters.add(hSeverityCombo);

        hStartField = darkField("");
        hStartField.setColumns(12);
        hStartField.setToolTipText("yyyy-MM-ddTHH:mm");
        filters.add(darkLabel("Start:")); filters.add(hStartField);

        hEndField = darkField("");
        hEndField.setColumns(12);
        hEndField.setToolTipText("yyyy-MM-ddTHH:mm");
        filters.add(darkLabel("End:")); filters.add(hEndField);

        filters.add(makeBtn("Search", ACCENT_BLUE, e -> searchHistory()));

        panel.add(filters, BorderLayout.NORTH);

        // History table
        String[] cols = {"ID", "Severity", "Sensor", "Zone", "Value",
                "Timestamp", "Message", "Status"};
        histModel = new DefaultTableModel(cols, 0) {
            @Override public boolean isCellEditable(int r, int c) { return false; }
        };
        histTable = new JTable(histModel);
        styleAlertTable(histTable);
        histTable.getColumnModel().getColumn(1).setCellRenderer(new SeverityBadgeRenderer());

        JScrollPane sp = new JScrollPane(histTable);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        panel.add(sp, BorderLayout.CENTER);

        return panel;
    }

    private void searchHistory() {
        String zone = (String) hZoneCombo.getSelectedItem();
        String zoneCode = "All".equals(zone) ? null : zone;

        String sensor = hSensorField.getText().trim();
        String sensorCode = sensor.isEmpty() ? null : sensor;

        String sev = (String) hSeverityCombo.getSelectedItem();
        SeverityLevel level = null;
        if ("WARNING".equals(sev))  level = SeverityLevel.WARNING;
        if ("CRITICAL".equals(sev)) level = SeverityLevel.CRITICAL;

        LocalDateTime start = parseDate(hStartField.getText().trim());
        LocalDateTime end   = parseDate(hEndField.getText().trim());

        List<Alert> results = farm.getAlertHistory(zoneCode, sensorCode, level, start, end);
        populateAlertTable(histModel, results);
    }

    // ═══════════════════════════ REFRESH ═══════════════════════════

    public void refreshAll() {
        refreshActiveTable();
        refreshStats();
        refreshOverview();
    }

    private void refreshActiveTable() {
        List<Alert> active = AlertManager.getActiveAlertsSortedBySeverity();
        populateAlertTable(activeModel, active);
    }

    private void populateAlertTable(DefaultTableModel model, List<Alert> alerts) {
        model.setRowCount(0);
        for (Alert a : alerts) {
            model.addRow(new Object[]{
                    a.getAlertId(),
                    a.getSeverityLevel().name(),
                    a.getSensorUniqueCode(),
                    a.getZoneId(),
                    String.format("%.2f", a.getReadingValue()),
                    a.getAlertTimestamp().format(DISPLAY_FMT),
                    a.getMessage(),
                    a.isAcknowledged() ? "Acknowledged" : "Pending"
            });
        }
    }

    private void refreshStats() {
        List<Alert> active = AlertManager.getActiveAlertsSortedBySeverity();
        long crit = active.stream().filter(a -> a.getSeverityLevel() == SeverityLevel.CRITICAL).count();
        long warn = active.stream().filter(a -> a.getSeverityLevel() == SeverityLevel.WARNING).count();
        critLabel.setText(String.valueOf(crit));
        warnLabel.setText(String.valueOf(warn));
        totalLabel.setText(String.valueOf(active.size()));
    }

    private void refreshOverview() {
        long crit = AlertManager.getActiveAlertsSortedBySeverity().stream()
                .filter(a -> a.getSeverityLevel() == SeverityLevel.CRITICAL).count();
        long warn = AlertManager.getActiveAlertsSortedBySeverity().stream()
                .filter(a -> a.getSeverityLevel() == SeverityLevel.WARNING).count();
        long norm = AlertManager.getActiveAlertsSortedBySeverity().stream()
                .filter(a -> a.getSeverityLevel() == SeverityLevel.NORMAL).count();
        ovCritical.setText("CRITICAL: " + crit + " alerts");
        ovWarning.setText("WARNING: " + warn + " alerts");
        ovNormal.setText("NORMAL: " + norm + " alerts");
    }

    // ═══════════════════════════ TABLE STYLING ═══════════════════════════

    private void styleAlertTable(JTable table) {
        table.setBackground(CARD_BG);
        table.setForeground(TEXT_WHITE);
        table.setGridColor(new Color(0x1A, 0x33, 0x50));
        table.setRowHeight(32);
        table.setFont(new Font("SansSerif", Font.PLAIN, 12));
        table.setSelectionBackground(ACCENT_BLUE);
        table.setSelectionForeground(TEXT_WHITE);
        table.setShowGrid(true);
        table.setIntercellSpacing(new Dimension(1, 1));

        JTableHeader header = table.getTableHeader();
        header.setBackground(ACCENT_BLUE);
        header.setForeground(TEXT_WHITE);
        header.setFont(new Font("SansSerif", Font.BOLD, 12));
        header.setReorderingAllowed(false);

        // Custom row colouring for severity tint
        DefaultTableModel model = (DefaultTableModel) table.getModel();
        table.setDefaultRenderer(Object.class, new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable t, Object v,
                                                           boolean sel, boolean foc, int r, int c) {
                Component comp = super.getTableCellRendererComponent(t, v, sel, foc, r, c);
                if (!sel) {
                    String severity = (String) t.getModel().getValueAt(r, 1);
                    if ("CRITICAL".equals(severity)) {
                        comp.setBackground(ROW_CRIT);
                    } else if ("WARNING".equals(severity)) {
                        comp.setBackground(ROW_WARN);
                    } else {
                        comp.setBackground(r % 2 == 0 ? CARD_BG : CARD_BG_ALT);
                    }
                    comp.setForeground(TEXT_WHITE);
                }
                return comp;
            }
        });
    }

    // ═══════════════════════════ HELPERS ═══════════════════════════

    private JButton makeBtn(String text, Color bg, ActionListener action) {
        JButton btn = new JButton(text);
        btn.setBackground(bg);
        btn.setForeground(TEXT_WHITE);
        btn.setFont(new Font("SansSerif", Font.BOLD, 12));
        btn.setFocusPainted(false);
        btn.setBorder(BorderFactory.createEmptyBorder(8, 18, 8, 18));
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { btn.setBackground(bg.brighter()); }
            @Override public void mouseExited(MouseEvent e)  { btn.setBackground(bg); }
        });
        if (action != null) btn.addActionListener(action);
        return btn;
    }

    private JLabel darkLabel(String text) {
        JLabel l = new JLabel(text);
        l.setForeground(TEXT_GRAY);
        l.setFont(new Font("SansSerif", Font.PLAIN, 12));
        return l;
    }

    private JTextField darkField(String text) {
        JTextField f = new JTextField(text);
        f.setBackground(CARD_BG_ALT);
        f.setForeground(TEXT_WHITE);
        f.setCaretColor(TEXT_WHITE);
        f.setFont(new Font("SansSerif", Font.PLAIN, 12));
        f.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ACCENT_BLUE, 1),
                BorderFactory.createEmptyBorder(4, 6, 4, 6)));
        return f;
    }

    private void styleCombo(JComboBox<String> combo) {
        combo.setBackground(CARD_BG_ALT);
        combo.setForeground(TEXT_WHITE);
        combo.setFont(new Font("SansSerif", Font.PLAIN, 12));
    }

    private LocalDateTime parseDate(String text) {
        if (text == null || text.isEmpty()) return null;
        try {
            return LocalDateTime.parse(text, PARSE_FMT);
        } catch (Exception e) {
            return null;
        }
    }

    private void warn(String msg) {
        JOptionPane.showMessageDialog(this, msg, "Warning", JOptionPane.WARNING_MESSAGE);
    }
}

package com.farm.demo.view;

import com.farm.demo.model.*;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.control.*;
import javafx.scene.layout.*;

/**
 * JavaFX view for alert management.
 * Displays active alerts and alert history from the AlertManager.
 */
public class AlertsView extends VBox {
    private static final String STYLE_DARK = "-fx-base: #0a1628; -fx-control-inner-background: #0d2137;";

    public AlertsView() {
        setStyle(STYLE_DARK);
        setPadding(new Insets(15));
        setSpacing(10);
        setFillWidth(true);

        // Title
        Label title = new Label("Alert Management");
        title.setStyle("-fx-font-size: 18; -fx-font-weight: bold; -fx-text-fill: white;");
        getChildren().add(title);

        // Stats bar
        HBox statsBar = buildStatsBar();
        getChildren().add(statsBar);

        // Tabbed pane: Active Alerts + History
        TabPane tabs = new TabPane();
        tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
        tabs.setStyle("-fx-background-color: #0a1628;");
        VBox.setVgrow(tabs, Priority.ALWAYS);

        Tab activeTab = new Tab("Active Alerts", buildActiveAlertsTable());
        activeTab.setStyle("-fx-text-fill: white;");

        Tab historyTab = new Tab("History", buildHistoryAlertsTable());
        historyTab.setStyle("-fx-text-fill: white;");

        tabs.getTabs().addAll(activeTab, historyTab);
        getChildren().add(tabs);
    }

    private HBox buildStatsBar() {
        HBox bar = new HBox(12);
        bar.setPrefHeight(80);
        bar.setStyle("-fx-fill: transparent;");

        try {
            java.util.List<com.farm.demo.model.Alert> allAlerts = AlertManager.getActiveAlertsSortedBySeverity();
            long critical = allAlerts.stream().filter(a -> a.getSeverityLevel() == SeverityLevel.CRITICAL).count();
            long warning = allAlerts.stream().filter(a -> a.getSeverityLevel() == SeverityLevel.WARNING).count();

            bar.getChildren().addAll(
                    makeStatCard("" + critical, "Critical", "#f44336"),
                    makeStatCard("" + warning, "Warnings", "#ffc107"),
                    makeStatCard("" + allAlerts.size(), "Total Active", "#0d2137")
            );
        } catch (Exception e) {
            bar.getChildren().addAll(
                    makeStatCard("—", "Critical", "#f44336"),
                    makeStatCard("—", "Warnings", "#ffc107"),
                    makeStatCard("—", "Total Active", "#0d2137")
            );
        }

        return bar;
    }

    private VBox makeStatCard(String value, String label, String color) {
        VBox card = new VBox(8);
        card.setPadding(new Insets(12));
        card.setStyle("-fx-border-color: " + color + "; -fx-border-radius: 8; -fx-background-color: #0d2137; -fx-background-radius: 8;");
        card.setPrefWidth(150);

        Label valLabel = new Label(value);
        valLabel.setStyle("-fx-font-size: 24; -fx-font-weight: bold; -fx-text-fill: " + color + ";");
        Label lblLabel = new Label(label);
        lblLabel.setStyle("-fx-font-size: 12; -fx-text-fill: #99aabb;");

        card.getChildren().addAll(valLabel, lblLabel);
        card.setAlignment(Pos.CENTER);
        return card;
    }

    private VBox buildActiveAlertsTable() {
        TableView<AlertRow> table = new TableView<>();
        table.setStyle("-fx-control-inner-background: #0d2137; -fx-table-cell-border-color: #1a3350;");

        TableColumn<AlertRow, String> zoneCol = new TableColumn<>("Zone");
        zoneCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().zone));

        TableColumn<AlertRow, String> sensorCol = new TableColumn<>("Sensor");
        sensorCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().sensor));

        TableColumn<AlertRow, String> messageCol = new TableColumn<>("Message");
        messageCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().message));
        messageCol.setPrefWidth(250);

        TableColumn<AlertRow, String> severityCol = new TableColumn<>("Severity");
        severityCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().severity));

        TableColumn<AlertRow, String> dateCol = new TableColumn<>("Timestamp");
        dateCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().timestamp));

        table.getColumns().addAll(zoneCol, sensorCol, messageCol, severityCol, dateCol);

        // Populate from AlertManager
        try {
            for (com.farm.demo.model.Alert alert : AlertManager.getActiveAlertsSortedBySeverity()) {
                table.getItems().add(new AlertRow(
                        alert.getZoneId(),
                        alert.getSensorUniqueCode(),
                        alert.getMessage(),
                        alert.getSeverityLevel().name(),
                        alert.getAlertTimestamp().toString()
                ));
            }
        } catch (Exception e) {
            // AlertManager might be empty
        }

        VBox pane = new VBox(table);
        VBox.setVgrow(table, Priority.ALWAYS);
        pane.setStyle("-fx-background-color: #0a1628;");
        return pane;
    }

    private VBox buildHistoryAlertsTable() {
        TableView<AlertRow> table = new TableView<>();
        table.setStyle("-fx-control-inner-background: #0d2137; -fx-table-cell-border-color: #1a3350;");

        TableColumn<AlertRow, String> zoneCol = new TableColumn<>("Zone");
        zoneCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().zone));

        TableColumn<AlertRow, String> sensorCol = new TableColumn<>("Sensor");
        sensorCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().sensor));

        TableColumn<AlertRow, String> messageCol = new TableColumn<>("Message");
        messageCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().message));
        messageCol.setPrefWidth(250);

        TableColumn<AlertRow, String> severityCol = new TableColumn<>("Severity");
        severityCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().severity));

        TableColumn<AlertRow, String> dateCol = new TableColumn<>("Timestamp");
        dateCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().timestamp));

        table.getColumns().addAll(zoneCol, sensorCol, messageCol, severityCol, dateCol);

        // Note: History is empty by default (AlertManager only tracks active alerts)
        // To show history, we would need to implement a persistence layer

        VBox pane = new VBox(table);
        VBox.setVgrow(table, Priority.ALWAYS);
        pane.setStyle("-fx-background-color: #0a1628;");
        return pane;
    }

    public static class AlertRow {
        public String zone, sensor, message, severity, timestamp;
        public AlertRow(String zone, String sensor, String message, String severity, String timestamp) {
            this.zone = zone;
            this.sensor = sensor;
            this.message = message;
            this.severity = severity;
            this.timestamp = timestamp;
        }
    }
}

package com.farm.demo.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.*;

/**
 * Root layout: fixed sidebar on the left, swappable content on the right.
 */
public class MainLayout extends HBox {

    private final StackPane contentHolder = new StackPane();

    // Keep references so we can highlight the active button
    private Button btnZones, btnLivestock, btnProduction;

    // Cached views (lazy-init)
    private Node zonesView;
    private Node livestockView;
    private Node productionView;

    public MainLayout() {
        getStyleClass().add("root");
        setFillHeight(true);

        VBox sidebar = buildSidebar();
        HBox.setHgrow(contentHolder, Priority.ALWAYS);
        contentHolder.setAlignment(Pos.TOP_LEFT);

        getChildren().addAll(sidebar, contentHolder);

        // Show zones by default
        showZones();
    }

    // ── Sidebar ───────────────────────────────────────────────────────────────

    private VBox buildSidebar() {
        VBox sidebar = new VBox();
        sidebar.getStyleClass().add("sidebar");
        VBox.setVgrow(sidebar, Priority.ALWAYS);

        // Header
        VBox header = new VBox(2);
        header.getStyleClass().add("sidebar-header");
        Label appTitle = new Label(" SmartFarm Core");
        appTitle.getStyleClass().add("sidebar-app-title");
        Label appSub = new Label("Management Suite");
        appSub.getStyleClass().add("sidebar-app-subtitle");
        header.getChildren().addAll(appTitle, appSub);

        // Spacer between header and nav
        Region topSpacer = new Region();
        topSpacer.setPrefHeight(8);

        // Nav buttons
        btnZones      = navButton("    Zones Overview");
        btnLivestock  = navButton("    Livestock Registry");
        btnProduction = navButton("    Production Records");

        btnZones.setOnAction(e -> showZones());
        btnLivestock.setOnAction(e -> showLivestock());
        btnProduction.setOnAction(e -> showProduction());

        // Push footer to bottom
        Region spacer = new Region();
        VBox.setVgrow(spacer, Priority.ALWAYS);

        // Footer (user info)
        VBox footer = buildFooter();

        sidebar.getChildren().addAll(
                header, topSpacer,
                btnZones, btnLivestock, btnProduction,
                spacer, footer
        );
        return sidebar;
    }

    private Button navButton(String text) {
        Button btn = new Button(text);
        btn.getStyleClass().add("sidebar-nav-btn");
        btn.setMaxWidth(Double.MAX_VALUE);
        return btn;
    }

    private VBox buildFooter() {
        VBox footer = new VBox(2);
        footer.getStyleClass().add("sidebar-footer");

        HBox userRow = new HBox(10);
        userRow.setAlignment(Pos.CENTER_LEFT);

        Label avatar = new Label("");
        avatar.setStyle("-fx-font-size:22px;");

        VBox userInfo = new VBox(1);
        Label userName = new Label("Manager Core");
        userName.getStyleClass().add("sidebar-user-name");
        Label userRole = new Label("ADMIN ACCESS");
        userRole.getStyleClass().add("sidebar-user-role");
        userInfo.getChildren().addAll(userName, userRole);

        userRow.getChildren().addAll(avatar, userInfo);
        footer.getChildren().add(userRow);
        return footer;
    }

    // ── Navigation ────────────────────────────────────────────────────────────

    private void setActive(Button active) {
        for (Button b : new Button[]{btnZones, btnLivestock, btnProduction}) {
            b.getStyleClass().remove("active");
        }
        active.getStyleClass().add("active");
    }

    private void showZones() {
        try {
            setActive(btnZones);
            if (zonesView == null) zonesView = new ZonesView();
            setContent(zonesView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Zones Overview");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showLivestock() {
        try {
            setActive(btnLivestock);
            if (livestockView == null) livestockView = new LivestockView();
            setContent(livestockView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Livestock Registry");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showProduction() {
        try {
            setActive(btnProduction);
            if (productionView == null) productionView = new ProductionView();
            setContent(productionView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Production Records");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void setContent(Node node) {
        contentHolder.getChildren().setAll(node);
        StackPane.setAlignment(node, Pos.TOP_LEFT);
    }
}

package com.farm.demo.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.*;

/**
 * Root layout: fixed sidebar on the left, swappable content on the right.
 */
public class MainLayout extends HBox {

    private final StackPane contentHolder = new StackPane();

    // Keep references so we can highlight the active button
    private Button btnZones, btnLivestock, btnProduction, btnSensors, btnAlerts;

    // Cached views (lazy-init)
    private Node zonesView;
    private Node livestockView;
    private Node productionView;
    private Node sensorsView;
    private Node alertsView;

    public MainLayout() {
        getStyleClass().add("root");
        setFillHeight(true);

        VBox sidebar = buildSidebar();
        HBox.setHgrow(contentHolder, Priority.ALWAYS);
        contentHolder.setAlignment(Pos.TOP_LEFT);

        getChildren().addAll(sidebar, contentHolder);

        // Show zones by default
        showZones();
    }

    // ── Sidebar ───────────────────────────────────────────────────────────────

    private VBox buildSidebar() {
        VBox sidebar = new VBox();
        sidebar.getStyleClass().add("sidebar");
        VBox.setVgrow(sidebar, Priority.ALWAYS);

        // Header
        VBox header = new VBox(2);
        header.getStyleClass().add("sidebar-header");
        Label appTitle = new Label(" SmartFarm Core");
        appTitle.getStyleClass().add("sidebar-app-title");
        Label appSub = new Label("Management Suite");
        appSub.getStyleClass().add("sidebar-app-subtitle");
        header.getChildren().addAll(appTitle, appSub);

        // Spacer between header and nav
        Region topSpacer = new Region();
        topSpacer.setPrefHeight(8);

        // Nav buttons
        btnZones      = navButton("    Zones Overview");
        btnLivestock  = navButton("    Livestock Registry");
        btnProduction = navButton("    Production Records");
        btnSensors    = navButton("    Sensors");
        btnAlerts     = navButton("    Alerts");

        btnZones.setOnAction(e -> showZones());
        btnLivestock.setOnAction(e -> showLivestock());
        btnProduction.setOnAction(e -> showProduction());
        btnSensors.setOnAction(e -> showSensors());
        btnAlerts.setOnAction(e -> showAlerts());

        // Push footer to bottom
        Region spacer = new Region();
        VBox.setVgrow(spacer, Priority.ALWAYS);

        // Footer (user info)
        VBox footer = buildFooter();

        sidebar.getChildren().addAll(
                header, topSpacer,
                btnZones, btnLivestock, btnProduction, btnSensors, btnAlerts,
                spacer, footer
        );
        return sidebar;
    }

    private Button navButton(String text) {
        Button btn = new Button(text);
        btn.getStyleClass().add("sidebar-nav-btn");
        btn.setMaxWidth(Double.MAX_VALUE);
        return btn;
    }

    private VBox buildFooter() {
        VBox footer = new VBox(2);
        footer.getStyleClass().add("sidebar-footer");

        HBox userRow = new HBox(10);
        userRow.setAlignment(Pos.CENTER_LEFT);

        Label avatar = new Label("");
        avatar.setStyle("-fx-font-size:22px;");

        VBox userInfo = new VBox(1);
        Label userName = new Label("Manager Core");
        userName.getStyleClass().add("sidebar-user-name");
        Label userRole = new Label("ADMIN ACCESS");
        userRole.getStyleClass().add("sidebar-user-role");
        userInfo.getChildren().addAll(userName, userRole);

        userRow.getChildren().addAll(avatar, userInfo);
        footer.getChildren().add(userRow);
        return footer;
    }

    // ── Navigation ────────────────────────────────────────────────────────────

    private void setActive(Button active) {
        for (Button b : new Button[]{btnZones, btnLivestock, btnProduction, btnSensors, btnAlerts}) {
            b.getStyleClass().remove("active");
        }
        active.getStyleClass().add("active");
    }

    private void openSwingGui() {
        try {
            // Launch the existing Swing SmartFarm GUI in its own thread. The Swing
            // class initializes its own sample data and runs on the Swing EDT.
            new Thread(() -> com.farm.demo.view.SmartFarmGUI.main(new String[0])).start();
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to launch Smart Farm (Swing)");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showZones() {
        try {
            setActive(btnZones);
            if (zonesView == null) zonesView = new ZonesView();
            setContent(zonesView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Zones Overview");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showLivestock() {
        try {
            setActive(btnLivestock);
            if (livestockView == null) livestockView = new LivestockView();
            setContent(livestockView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Livestock Registry");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showProduction() {
        try {
            setActive(btnProduction);
            if (productionView == null) productionView = new ProductionView();
            setContent(productionView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Production Records");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showSensors() {
        try {
            setActive(btnSensors);
            if (sensorsView == null) sensorsView = new SensorsView();
            setContent(sensorsView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Sensors");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void showAlerts() {
        try {
            setActive(btnAlerts);
            if (alertsView == null) alertsView = new AlertsView();
            setContent(alertsView);
        } catch (Exception e) {
            e.printStackTrace();
            javafx.scene.control.Alert alert = new javafx.scene.control.Alert(javafx.scene.control.Alert.AlertType.ERROR);
            alert.setTitle("Error");
            alert.setHeaderText("Failed to load Alerts");
            alert.setContentText(e.getClass().getSimpleName() + ": " + e.getMessage());
            alert.showAndWait();
        }
    }

    private void setContent(Node node) {
        contentHolder.getChildren().setAll(node);
        StackPane.setAlignment(node, Pos.TOP_LEFT);
    }
}

package com.farm.demo.view;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class SensorManagementPanel extends JPanel {

    // ── Theme colours ──
    private static final Color BG_DARK      = new Color(0x0A, 0x16, 0x28);
    private static final Color CARD_BG      = new Color(0x0D, 0x21, 0x37);
    private static final Color CARD_BG_ALT  = new Color(0x11, 0x22, 0x44);
    private static final Color ACCENT_BLUE  = new Color(0x15, 0x65, 0xC0);
    private static final Color ACCENT_GREEN = new Color(0x00, 0xE6, 0x76);
    private static final Color ACCENT_AMBER = new Color(0xFF, 0xC1, 0x07);
    private static final Color ACCENT_RED   = new Color(0xF4, 0x43, 0x36);
    private static final Color TEXT_WHITE    = Color.WHITE;
    private static final Color TEXT_GRAY     = new Color(0x99, 0xAA, 0xBB);
    private static final Color GREEN_TINT   = new Color(0x0A, 0x2E, 0x1A);
    private static final Color AMBER_TINT   = new Color(0x2E, 0x25, 0x0A);
    private static final Color RED_TINT     = new Color(0x2E, 0x0F, 0x0A);

    private final Farm farm;
    private DefaultTableModel sensorTableModel;
    private JTable sensorTable;
    private final List<String[]> rowMeta = new ArrayList<>(); // [zoneCode, sensorCode]

    // Stats labels
    private JLabel totalLabel, activeLabel, faultyLabel;

    // Dashboard
    private JComboBox<String> zoneDashCombo;
    private JPanel dashboardCards;
    private final List<String> zoneCodesList = new ArrayList<>();

    public SensorManagementPanel(Farm farm) {
        this.farm = farm;
        setLayout(new BorderLayout(10, 10));
        setBackground(BG_DARK);
        setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        add(buildStatsBar(), BorderLayout.NORTH);

        // Center: table + dashboard in a split
        JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,
                buildTablePanel(), buildDashboardPanel());
        split.setResizeWeight(0.65);
        split.setDividerSize(6);
        split.setBackground(BG_DARK);
        split.setBorder(null);
        add(split, BorderLayout.CENTER);

        add(buildActionBar(), BorderLayout.SOUTH);

        refreshAll();
    }

    // ═══════════════════════════ A) STATS BAR ═══════════════════════════

    private JPanel buildStatsBar() {
        JPanel bar = new JPanel(new GridLayout(1, 3, 12, 0));
        bar.setOpaque(false);
        bar.setPreferredSize(new Dimension(0, 80));

        totalLabel  = new JLabel("0", SwingConstants.CENTER);
        activeLabel = new JLabel("0", SwingConstants.CENTER);
        faultyLabel = new JLabel("0", SwingConstants.CENTER);

        bar.add(makeStatCard(totalLabel,  "Total Sensors", CARD_BG));
        bar.add(makeStatCard(activeLabel, "Active",        CARD_BG));
        bar.add(makeStatCard(faultyLabel, "Faulty / Suspended", CARD_BG));
        return bar;
    }

    private RoundedPanel makeStatCard(JLabel numLabel, String subtitle, Color bg) {
        RoundedPanel card = new RoundedPanel(bg, 16);
        card.setLayout(new BorderLayout());
        numLabel.setFont(new Font("SansSerif", Font.BOLD, 28));
        numLabel.setForeground(TEXT_WHITE);
        JLabel sub = new JLabel(subtitle, SwingConstants.CENTER);
        sub.setFont(new Font("SansSerif", Font.PLAIN, 12));
        sub.setForeground(TEXT_GRAY);
        card.add(numLabel, BorderLayout.CENTER);
        card.add(sub, BorderLayout.SOUTH);
        card.setBorder(BorderFactory.createEmptyBorder(8, 10, 10, 10));
        return card;
    }

    // ═══════════════════════════ B) SENSOR TABLE ═══════════════════════════

    private JPanel buildTablePanel() {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(BG_DARK);

        String[] cols = {"Sensor Code", "Zone", "Type", "Unit",
                "Min Threshold", "Max Threshold", "Last Value", "Status"};
        sensorTableModel = new DefaultTableModel(cols, 0) {
            @Override public boolean isCellEditable(int r, int c) { return false; }
        };
        sensorTable = new JTable(sensorTableModel);
        styleTable(sensorTable);
        sensorTable.getColumnModel().getColumn(7).setCellRenderer(new StatusBadgeRenderer());

        JScrollPane sp = new JScrollPane(sensorTable);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        panel.add(sp, BorderLayout.CENTER);
        return panel;
    }

    // ═══════════════════════════ C) ACTION BAR ═══════════════════════════

    private JPanel buildActionBar() {
        JPanel bar = new JPanel(new FlowLayout(FlowLayout.CENTER, 10, 8));
        bar.setBackground(CARD_BG);
        bar.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));

        bar.add(makeBtn("Suspend",    ACCENT_AMBER, e -> changeStatus(SensorStatus.SUSPENDED)));
        bar.add(makeBtn("Reactivate", ACCENT_GREEN, e -> changeStatus(SensorStatus.ACTIVE)));
        bar.add(makeBtn("Mark Faulty",ACCENT_RED,   e -> changeStatus(SensorStatus.FAULTY)));
        bar.add(makeBtn("Update Thresholds", ACCENT_BLUE, e -> openThresholdDialog()));
        bar.add(makeBtn("Add Reading",       ACCENT_BLUE, e -> openAddReadingDialog()));
        bar.add(makeBtn("View History",      ACCENT_BLUE, e -> openHistoryDialog()));
        return bar;
    }

    // ═══════════════════════════ D) DASHBOARD ═══════════════════════════

    private JPanel buildDashboardPanel() {
        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.setBackground(BG_DARK);
        panel.setBorder(BorderFactory.createEmptyBorder(0, 8, 0, 0));

        JLabel title = new JLabel("  Readings Dashboard");
        title.setFont(new Font("SansSerif", Font.BOLD, 14));
        title.setForeground(TEXT_WHITE);

        zoneDashCombo = new JComboBox<>();
        zoneDashCombo.setBackground(CARD_BG);
        zoneDashCombo.setForeground(TEXT_WHITE);
        zoneDashCombo.setFont(new Font("SansSerif", Font.PLAIN, 12));
        zoneDashCombo.addActionListener(e -> refreshDashboard());

        JPanel top = new JPanel(new BorderLayout(6, 0));
        top.setOpaque(false);
        top.add(title, BorderLayout.WEST);
        top.add(zoneDashCombo, BorderLayout.CENTER);
        panel.add(top, BorderLayout.NORTH);

        dashboardCards = new JPanel(new GridLayout(0, 2, 8, 8));
        dashboardCards.setOpaque(false);
        JScrollPane sp = new JScrollPane(dashboardCards);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        sp.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        panel.add(sp, BorderLayout.CENTER);
        return panel;
    }

    // ═══════════════════════════ ACTIONS ═══════════════════════════

    private void changeStatus(SensorStatus newStatus) {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];
        String msg = farm.changeSensorStatus(zoneCode, sensorCode, newStatus);
        JOptionPane.showMessageDialog(this, msg);
        refreshAll();
    }

    private void openThresholdDialog() {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];

        Optional<Zone> zOpt = farm.getZoneByCode(zoneCode);
        if (zOpt.isEmpty()) return;
        Optional<Sensor> sOpt = zOpt.get().getSensorByUniqueCode(sensorCode);
        if (sOpt.isEmpty()) return;
        Sensor sensor = sOpt.get();
        boolean isGPS = sensor instanceof GPSCollarSensor;

        JDialog dlg = darkDialog("Update Thresholds", 360, isGPS ? 300 : 200);
        JPanel form = new JPanel(new GridLayout(0, 2, 8, 8));
        form.setOpaque(false);

        JTextField minF = darkField(String.valueOf(sensor.getMinThreshold()));
        JTextField maxF = darkField(String.valueOf(sensor.getMaxThreshold()));
        form.add(darkLabel("Min Threshold:")); form.add(minF);
        form.add(darkLabel("Max Threshold:")); form.add(maxF);

        JTextField minLong = null, maxLong = null;
        if (isGPS) {
            GPSCollarSensor gps = (GPSCollarSensor) sensor;
            minLong = darkField(String.valueOf(gps.getMinThresLong()));
            maxLong = darkField(String.valueOf(gps.getMaxThresLong()));
            form.add(darkLabel("Min Longitude:")); form.add(minLong);
            form.add(darkLabel("Max Longitude:")); form.add(maxLong);
        }

        JButton save = makeBtn("Save", ACCENT_BLUE, null);
        JTextField fMinLong = minLong, fMaxLong = maxLong;
        save.addActionListener(ev -> {
            try {
                double mn = Double.parseDouble(minF.getText().trim());
                double mx = Double.parseDouble(maxF.getText().trim());
                Double mnL = null, mxL = null;
                if (isGPS) {
                    mnL = Double.parseDouble(fMinLong.getText().trim());
                    mxL = Double.parseDouble(fMaxLong.getText().trim());
                }
                String msg = farm.updateSensorThresholds(zoneCode, sensorCode, mn, mx, mnL, mxL);
                JOptionPane.showMessageDialog(dlg, msg);
                dlg.dispose();
                refreshAll();
            } catch (ThresholdException ex) {
                JOptionPane.showMessageDialog(dlg, ex.getMessage(), "Threshold Error", JOptionPane.ERROR_MESSAGE);
            } catch (NumberFormatException ex) {
                JOptionPane.showMessageDialog(dlg, "Please enter valid numbers.", "Input Error", JOptionPane.ERROR_MESSAGE);
            }
        });

        dlg.add(form, BorderLayout.CENTER);
        dlg.add(wrapButton(save), BorderLayout.SOUTH);
        dlg.setVisible(true);
    }

    private void openAddReadingDialog() {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];

        Optional<Zone> zOpt = farm.getZoneByCode(zoneCode);
        if (zOpt.isEmpty()) return;
        Optional<Sensor> sOpt = zOpt.get().getSensorByUniqueCode(sensorCode);
        if (sOpt.isEmpty()) return;
        boolean isGPS = sOpt.get() instanceof GPSCollarSensor;

        JDialog dlg = darkDialog("Add Reading", 340, isGPS ? 200 : 160);
        JPanel form = new JPanel(new GridLayout(0, 2, 8, 8));
        form.setOpaque(false);

        JTextField valF = darkField("");
        form.add(darkLabel(isGPS ? "Latitude:" : "Value:")); form.add(valF);

        JTextField lonF = null;
        if (isGPS) {
            lonF = darkField("");
            form.add(darkLabel("Longitude:")); form.add(lonF);
        }

        JButton submit = makeBtn("Submit", ACCENT_BLUE, null);
        JTextField fLon = lonF;
        submit.addActionListener(ev -> {
            try {
                double v = Double.parseDouble(valF.getText().trim());
                String msg;
                if (isGPS) {
                    double lon = Double.parseDouble(fLon.getText().trim());
                    msg = farm.addSensorReading(zoneCode, sensorCode, v, lon);
                } else {
                    msg = farm.addSensorReading(zoneCode, sensorCode, v);
                }
                JOptionPane.showMessageDialog(dlg, msg);
                dlg.dispose();
                refreshAll();
            } catch (ThresholdException ex) {
                JOptionPane.showMessageDialog(dlg, ex.getMessage(), "Threshold Error", JOptionPane.ERROR_MESSAGE);
            } catch (NumberFormatException ex) {
                JOptionPane.showMessageDialog(dlg, "Please enter valid numbers.", "Input Error", JOptionPane.ERROR_MESSAGE);
            }
        });

        dlg.add(form, BorderLayout.CENTER);
        dlg.add(wrapButton(submit), BorderLayout.SOUTH);
        dlg.setVisible(true);
    }

    private void openHistoryDialog() {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];

        JDialog dlg = darkDialog("Sensor Reading History", 520, 420);
        JPanel form = new JPanel(new GridLayout(1, 4, 6, 0));
        form.setOpaque(false);
        form.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        JTextField startF = darkField("yyyy-MM-ddTHH:mm");
        JTextField endF   = darkField("yyyy-MM-ddTHH:mm");
        form.add(darkLabel("Start:")); form.add(startF);
        form.add(darkLabel("End:"));   form.add(endF);

        JTextArea area = new JTextArea();
        area.setEditable(false);
        area.setBackground(CARD_BG);
        area.setForeground(TEXT_WHITE);
        area.setFont(new Font("SansSerif", Font.PLAIN, 12));
        area.setCaretColor(TEXT_WHITE);
        JScrollPane sp = new JScrollPane(area);
        sp.setBorder(BorderFactory.createEmptyBorder());

        JButton search = makeBtn("Search", ACCENT_BLUE, ev -> {
            DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm");
            LocalDateTime start = null, end = null;
            try {
                String st = startF.getText().trim();
                if (!st.isEmpty() && !st.equals("yyyy-MM-ddTHH:mm"))
                    start = LocalDateTime.parse(st, fmt);
                String en = endF.getText().trim();
                if (!en.isEmpty() && !en.equals("yyyy-MM-ddTHH:mm"))
                    end = LocalDateTime.parse(en, fmt);
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(dlg, "Invalid date format. Use yyyy-MM-ddTHH:mm", "Error", JOptionPane.ERROR_MESSAGE);
                return;
            }
            String result = farm.browseSensorReadingHistory(zoneCode, sensorCode, start, end);
            area.setText(result);
        });

        JPanel top = new JPanel(new BorderLayout(6, 0));
        top.setOpaque(false);
        top.add(form, BorderLayout.CENTER);
        top.add(search, BorderLayout.EAST);

        dlg.add(top, BorderLayout.NORTH);
        dlg.add(sp, BorderLayout.CENTER);
        dlg.setVisible(true);
    }

    // ═══════════════════════════ REFRESH ═══════════════════════════

    public void refreshAll() {
        refreshTable();
        refreshStats();
        refreshZoneCombo();
        refreshDashboard();
    }

    private void refreshTable() {
        sensorTableModel.setRowCount(0);
        rowMeta.clear();
        for (Zone zone : farm.getZones()) {
            for (Sensor s : zone.getSensors()) {
                String lastVal = s.getLastReadingValue()
                        .map(v -> String.format("%.2f", v))
                        .orElse("No reading yet");
                sensorTableModel.addRow(new Object[]{
                        s.getUniqueCode(), zone.getCode(),
                        s.getClass().getSimpleName(), s.getUnitOfMeasurement(),
                        s.getMinThreshold(), s.getMaxThreshold(),
                        lastVal, s.getStatus().name()
                });
                rowMeta.add(new String[]{zone.getCode(), s.getUniqueCode()});
            }
        }
    }

    private void refreshStats() {
        int total = 0, active = 0, faulty = 0;
        for (Zone z : farm.getZones()) {
            for (Sensor s : z.getSensors()) {
                total++;
                if (s.getStatus() == SensorStatus.ACTIVE) active++;
                else faulty++;
            }
        }
        totalLabel.setText(String.valueOf(total));
        activeLabel.setText(String.valueOf(active));
        faultyLabel.setText(String.valueOf(faulty));
    }

    private void refreshZoneCombo() {
        zoneDashCombo.removeAllItems();
        zoneCodesList.clear();
        for (Zone z : farm.getZones()) {
            zoneDashCombo.addItem(z.getName() + " (" + z.getCode() + ")");
            zoneCodesList.add(z.getCode());
        }
    }

    private void refreshDashboard() {
        dashboardCards.removeAll();
        int idx = zoneDashCombo.getSelectedIndex();
        if (idx < 0 || idx >= zoneCodesList.size()) { dashboardCards.revalidate(); dashboardCards.repaint(); return; }
        String zc = zoneCodesList.get(idx);
        Optional<Zone> zOpt = farm.getZoneByCode(zc);
        if (zOpt.isEmpty()) return;

        for (Sensor s : zOpt.get().getSensors()) {
            Color tint = CARD_BG;
            Optional<Double> lastVal = s.getLastReadingValue();
            String valText = "No reading yet";
            if (lastVal.isPresent()) {
                double v = lastVal.get();
                valText = String.format("%.2f %s", v, s.getUnitOfMeasurement());
                Object[] st = s.getReadingStatus(v);
                String level = (String) st[1];
                if ("Critical".equals(level)) tint = RED_TINT;
                else if ("Warning".equals(level)) tint = AMBER_TINT;
                else tint = GREEN_TINT;
            }

            RoundedPanel card = new RoundedPanel(tint, 14);
            card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
            card.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));

            JLabel code = new JLabel(s.getUniqueCode());
            code.setFont(new Font("SansSerif", Font.BOLD, 12));
            code.setForeground(TEXT_WHITE);
            code.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel val = new JLabel(valText);
            val.setFont(new Font("SansSerif", Font.PLAIN, 11));
            val.setForeground(TEXT_GRAY);
            val.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel badge = new JLabel(s.getStatus().name());
            badge.setFont(new Font("SansSerif", Font.BOLD, 10));
            badge.setOpaque(true);
            badge.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
            badge.setAlignmentX(Component.LEFT_ALIGNMENT);
            switch (s.getStatus()) {
                case ACTIVE:    badge.setForeground(ACCENT_GREEN); badge.setBackground(new Color(0x00,0x3D,0x20)); break;
                case SUSPENDED: badge.setForeground(ACCENT_AMBER); badge.setBackground(new Color(0x4E,0x39,0x00)); break;
                case FAULTY:    badge.setForeground(ACCENT_RED);   badge.setBackground(new Color(0x4A,0x0E,0x0A)); break;
            }

            card.add(code); card.add(Box.createVerticalStrut(4));
            card.add(val);  card.add(Box.createVerticalStrut(4));
            card.add(badge);
            dashboardCards.add(card);
        }
        dashboardCards.revalidate();
        dashboardCards.repaint();
    }

    // ═══════════════════════════ HELPERS ═══════════════════════════

    private void styleTable(JTable table) {
        table.setBackground(CARD_BG);
        table.setForeground(TEXT_WHITE);
        table.setGridColor(new Color(0x1A, 0x33, 0x50));
        table.setRowHeight(32);
        table.setFont(new Font("SansSerif", Font.PLAIN, 12));
        table.setSelectionBackground(ACCENT_BLUE);
        table.setSelectionForeground(TEXT_WHITE);
        table.setShowGrid(true);
        table.setIntercellSpacing(new Dimension(1, 1));

        JTableHeader header = table.getTableHeader();
        header.setBackground(ACCENT_BLUE);
        header.setForeground(TEXT_WHITE);
        header.setFont(new Font("SansSerif", Font.BOLD, 12));
        header.setReorderingAllowed(false);

        table.setDefaultRenderer(Object.class, new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable t, Object v,
                                                           boolean sel, boolean foc, int r, int c) {
                Component comp = super.getTableCellRendererComponent(t, v, sel, foc, r, c);
                if (!sel) {
                    comp.setBackground(r % 2 == 0 ? CARD_BG : CARD_BG_ALT);
                    comp.setForeground(TEXT_WHITE);
                }
                return comp;
            }
        });
    }

    private JButton makeBtn(String text, Color bg, ActionListener action) {
        JButton btn = new JButton(text);
        btn.setBackground(bg);
        btn.setForeground(TEXT_WHITE);
        btn.setFont(new Font("SansSerif", Font.BOLD, 12));
        btn.setFocusPainted(false);
        btn.setBorder(BorderFactory.createEmptyBorder(8, 18, 8, 18));
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { btn.setBackground(bg.brighter()); }
            @Override public void mouseExited(MouseEvent e)  { btn.setBackground(bg); }
        });
        if (action != null) btn.addActionListener(action);
        return btn;
    }

    private JDialog darkDialog(String title, int w, int h) {
        JDialog dlg = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), title, true);
        dlg.setSize(w, h);
        dlg.setLocationRelativeTo(this);
        dlg.getContentPane().setBackground(BG_DARK);
        dlg.setLayout(new BorderLayout(10, 10));
        ((JPanel) dlg.getContentPane()).setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        return dlg;
    }

    private JLabel darkLabel(String text) {
        JLabel l = new JLabel(text);
        l.setForeground(TEXT_GRAY);
        l.setFont(new Font("SansSerif", Font.PLAIN, 12));
        return l;
    }

    private JTextField darkField(String text) {
        JTextField f = new JTextField(text);
        f.setBackground(CARD_BG_ALT);
        f.setForeground(TEXT_WHITE);
        f.setCaretColor(TEXT_WHITE);
        f.setFont(new Font("SansSerif", Font.PLAIN, 12));
        f.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ACCENT_BLUE, 1),
                BorderFactory.createEmptyBorder(4, 6, 4, 6)));
        return f;
    }

    private JPanel wrapButton(JButton btn) {
        JPanel p = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        p.setOpaque(false);
        p.add(btn);
        return p;
    }

    private void warn(String msg) {
        JOptionPane.showMessageDialog(this, msg, "Warning", JOptionPane.WARNING_MESSAGE);
    }
}

package com.farm.demo.view;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import com.farm.demo.model.*;

public class SensorManagementPanel extends JPanel {

    // ── Theme colours ──
    private static final Color BG_DARK      = new Color(0x0A, 0x16, 0x28);
    private static final Color CARD_BG      = new Color(0x0D, 0x21, 0x37);
    private static final Color CARD_BG_ALT  = new Color(0x11, 0x22, 0x44);
    private static final Color ACCENT_BLUE  = new Color(0x15, 0x65, 0xC0);
    private static final Color ACCENT_GREEN = new Color(0x00, 0xE6, 0x76);
    private static final Color ACCENT_AMBER = new Color(0xFF, 0xC1, 0x07);
    private static final Color ACCENT_RED   = new Color(0xF4, 0x43, 0x36);
    private static final Color TEXT_WHITE    = Color.WHITE;
    private static final Color TEXT_GRAY     = new Color(0x99, 0xAA, 0xBB);
    private static final Color GREEN_TINT   = new Color(0x0A, 0x2E, 0x1A);
    private static final Color AMBER_TINT   = new Color(0x2E, 0x25, 0x0A);
    private static final Color RED_TINT     = new Color(0x2E, 0x0F, 0x0A);

    private final Farm farm;
    private DefaultTableModel sensorTableModel;
    private JTable sensorTable;
    private final List<String[]> rowMeta = new ArrayList<>(); // [zoneCode, sensorCode]

    // Stats labels
    private JLabel totalLabel, activeLabel, faultyLabel;

    // Dashboard
    private JComboBox<String> zoneDashCombo;
    private JPanel dashboardCards;
    private final List<String> zoneCodesList = new ArrayList<>();

    public SensorManagementPanel(Farm farm) {
        this.farm = farm;
        setLayout(new BorderLayout(10, 10));
        setBackground(BG_DARK);
        setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        add(buildStatsBar(), BorderLayout.NORTH);

        // Center: table + dashboard in a split
        JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,
                buildTablePanel(), buildDashboardPanel());
        split.setResizeWeight(0.65);
        split.setDividerSize(6);
        split.setBackground(BG_DARK);
        split.setBorder(null);
        add(split, BorderLayout.CENTER);

        add(buildActionBar(), BorderLayout.SOUTH);

        refreshAll();
    }

    // ═══════════════════════════ A) STATS BAR ═══════════════════════════

    private JPanel buildStatsBar() {
        JPanel bar = new JPanel(new GridLayout(1, 3, 12, 0));
        bar.setOpaque(false);
        bar.setPreferredSize(new Dimension(0, 80));

        totalLabel  = new JLabel("0", SwingConstants.CENTER);
        activeLabel = new JLabel("0", SwingConstants.CENTER);
        faultyLabel = new JLabel("0", SwingConstants.CENTER);

        bar.add(makeStatCard(totalLabel,  "Total Sensors", CARD_BG));
        bar.add(makeStatCard(activeLabel, "Active",        CARD_BG));
        bar.add(makeStatCard(faultyLabel, "Faulty / Suspended", CARD_BG));
        return bar;
    }

    private RoundedPanel makeStatCard(JLabel numLabel, String subtitle, Color bg) {
        RoundedPanel card = new RoundedPanel(bg, 16);
        card.setLayout(new BorderLayout());
        numLabel.setFont(new Font("SansSerif", Font.BOLD, 28));
        numLabel.setForeground(TEXT_WHITE);
        JLabel sub = new JLabel(subtitle, SwingConstants.CENTER);
        sub.setFont(new Font("SansSerif", Font.PLAIN, 12));
        sub.setForeground(TEXT_GRAY);
        card.add(numLabel, BorderLayout.CENTER);
        card.add(sub, BorderLayout.SOUTH);
        card.setBorder(BorderFactory.createEmptyBorder(8, 10, 10, 10));
        return card;
    }

    // ═══════════════════════════ B) SENSOR TABLE ═══════════════════════════

    private JPanel buildTablePanel() {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(BG_DARK);

        String[] cols = {"Sensor Code", "Zone", "Type", "Unit",
                "Min Threshold", "Max Threshold", "Last Value", "Status"};
        sensorTableModel = new DefaultTableModel(cols, 0) {
            @Override public boolean isCellEditable(int r, int c) { return false; }
        };
        sensorTable = new JTable(sensorTableModel);
        styleTable(sensorTable);
        sensorTable.getColumnModel().getColumn(7).setCellRenderer(new StatusBadgeRenderer());

        JScrollPane sp = new JScrollPane(sensorTable);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        panel.add(sp, BorderLayout.CENTER);
        return panel;
    }

    // ═══════════════════════════ C) ACTION BAR ═══════════════════════════

    private JPanel buildActionBar() {
        JPanel bar = new JPanel(new FlowLayout(FlowLayout.CENTER, 10, 8));
        bar.setBackground(CARD_BG);
        bar.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));

        bar.add(makeBtn("Suspend",    ACCENT_AMBER, e -> changeStatus(SensorStatus.SUSPENDED)));
        bar.add(makeBtn("Reactivate", ACCENT_GREEN, e -> changeStatus(SensorStatus.ACTIVE)));
        bar.add(makeBtn("Mark Faulty",ACCENT_RED,   e -> changeStatus(SensorStatus.FAULTY)));
        bar.add(makeBtn("Update Thresholds", ACCENT_BLUE, e -> openThresholdDialog()));
        bar.add(makeBtn("Add Reading",       ACCENT_BLUE, e -> openAddReadingDialog()));
        bar.add(makeBtn("View History",      ACCENT_BLUE, e -> openHistoryDialog()));
        return bar;
    }

    // ═══════════════════════════ D) DASHBOARD ═══════════════════════════

    private JPanel buildDashboardPanel() {
        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.setBackground(BG_DARK);
        panel.setBorder(BorderFactory.createEmptyBorder(0, 8, 0, 0));

        JLabel title = new JLabel("  Readings Dashboard");
        title.setFont(new Font("SansSerif", Font.BOLD, 14));
        title.setForeground(TEXT_WHITE);

        zoneDashCombo = new JComboBox<>();
        zoneDashCombo.setBackground(CARD_BG);
        zoneDashCombo.setForeground(TEXT_WHITE);
        zoneDashCombo.setFont(new Font("SansSerif", Font.PLAIN, 12));
        zoneDashCombo.addActionListener(e -> refreshDashboard());

        JPanel top = new JPanel(new BorderLayout(6, 0));
        top.setOpaque(false);
        top.add(title, BorderLayout.WEST);
        top.add(zoneDashCombo, BorderLayout.CENTER);
        panel.add(top, BorderLayout.NORTH);

        dashboardCards = new JPanel(new GridLayout(0, 2, 8, 8));
        dashboardCards.setOpaque(false);
        JScrollPane sp = new JScrollPane(dashboardCards);
        sp.getViewport().setBackground(BG_DARK);
        sp.setBorder(BorderFactory.createEmptyBorder());
        sp.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        panel.add(sp, BorderLayout.CENTER);
        return panel;
    }

    // ═══════════════════════════ ACTIONS ═══════════════════════════

    private void changeStatus(SensorStatus newStatus) {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];
        String msg = farm.changeSensorStatus(zoneCode, sensorCode, newStatus);
        JOptionPane.showMessageDialog(this, msg);
        refreshAll();
    }

    private void openThresholdDialog() {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];

        Optional<Zone> zOpt = farm.getZoneByCode(zoneCode);
        if (zOpt.isEmpty()) return;
        Optional<Sensor> sOpt = zOpt.get().getSensorByUniqueCode(sensorCode);
        if (sOpt.isEmpty()) return;
        Sensor sensor = sOpt.get();
        boolean isGPS = sensor instanceof GPSCollarSensor;

        JDialog dlg = darkDialog("Update Thresholds", 360, isGPS ? 300 : 200);
        JPanel form = new JPanel(new GridLayout(0, 2, 8, 8));
        form.setOpaque(false);

        JTextField minF = darkField(String.valueOf(sensor.getMinThreshold()));
        JTextField maxF = darkField(String.valueOf(sensor.getMaxThreshold()));
        form.add(darkLabel("Min Threshold:")); form.add(minF);
        form.add(darkLabel("Max Threshold:")); form.add(maxF);

        JTextField minLong = null, maxLong = null;
        if (isGPS) {
            GPSCollarSensor gps = (GPSCollarSensor) sensor;
            minLong = darkField(String.valueOf(gps.getMinThresLong()));
            maxLong = darkField(String.valueOf(gps.getMaxThresLong()));
            form.add(darkLabel("Min Longitude:")); form.add(minLong);
            form.add(darkLabel("Max Longitude:")); form.add(maxLong);
        }

        JButton save = makeBtn("Save", ACCENT_BLUE, null);
        JTextField fMinLong = minLong, fMaxLong = maxLong;
        save.addActionListener(ev -> {
            try {
                double mn = Double.parseDouble(minF.getText().trim());
                double mx = Double.parseDouble(maxF.getText().trim());
                Double mnL = null, mxL = null;
                if (isGPS) {
                    mnL = Double.parseDouble(fMinLong.getText().trim());
                    mxL = Double.parseDouble(fMaxLong.getText().trim());
                }
                String msg = farm.updateSensorThresholds(zoneCode, sensorCode, mn, mx, mnL, mxL);
                JOptionPane.showMessageDialog(dlg, msg);
                dlg.dispose();
                refreshAll();
            } catch (ThresholdException ex) {
                JOptionPane.showMessageDialog(dlg, ex.getMessage(), "Threshold Error", JOptionPane.ERROR_MESSAGE);
            } catch (NumberFormatException ex) {
                JOptionPane.showMessageDialog(dlg, "Please enter valid numbers.", "Input Error", JOptionPane.ERROR_MESSAGE);
            }
        });

        dlg.add(form, BorderLayout.CENTER);
        dlg.add(wrapButton(save), BorderLayout.SOUTH);
        dlg.setVisible(true);
    }

    private void openAddReadingDialog() {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];

        Optional<Zone> zOpt = farm.getZoneByCode(zoneCode);
        if (zOpt.isEmpty()) return;
        Optional<Sensor> sOpt = zOpt.get().getSensorByUniqueCode(sensorCode);
        if (sOpt.isEmpty()) return;
        boolean isGPS = sOpt.get() instanceof GPSCollarSensor;

        JDialog dlg = darkDialog("Add Reading", 340, isGPS ? 200 : 160);
        JPanel form = new JPanel(new GridLayout(0, 2, 8, 8));
        form.setOpaque(false);

        JTextField valF = darkField("");
        form.add(darkLabel(isGPS ? "Latitude:" : "Value:")); form.add(valF);

        JTextField lonF = null;
        if (isGPS) {
            lonF = darkField("");
            form.add(darkLabel("Longitude:")); form.add(lonF);
        }

        JButton submit = makeBtn("Submit", ACCENT_BLUE, null);
        JTextField fLon = lonF;
        submit.addActionListener(ev -> {
            try {
                double v = Double.parseDouble(valF.getText().trim());
                String msg;
                if (isGPS) {
                    double lon = Double.parseDouble(fLon.getText().trim());
                    msg = farm.addSensorReading(zoneCode, sensorCode, v, lon);
                } else {
                    msg = farm.addSensorReading(zoneCode, sensorCode, v);
                }
                JOptionPane.showMessageDialog(dlg, msg);
                dlg.dispose();
                refreshAll();
            } catch (ThresholdException ex) {
                JOptionPane.showMessageDialog(dlg, ex.getMessage(), "Threshold Error", JOptionPane.ERROR_MESSAGE);
            } catch (NumberFormatException ex) {
                JOptionPane.showMessageDialog(dlg, "Please enter valid numbers.", "Input Error", JOptionPane.ERROR_MESSAGE);
            }
        });

        dlg.add(form, BorderLayout.CENTER);
        dlg.add(wrapButton(submit), BorderLayout.SOUTH);
        dlg.setVisible(true);
    }

    private void openHistoryDialog() {
        int row = sensorTable.getSelectedRow();
        if (row < 0) { warn("Please select a sensor first."); return; }
        String zoneCode   = rowMeta.get(row)[0];
        String sensorCode = rowMeta.get(row)[1];

        JDialog dlg = darkDialog("Sensor Reading History", 520, 420);
        JPanel form = new JPanel(new GridLayout(1, 4, 6, 0));
        form.setOpaque(false);
        form.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

        JTextField startF = darkField("yyyy-MM-ddTHH:mm");
        JTextField endF   = darkField("yyyy-MM-ddTHH:mm");
        form.add(darkLabel("Start:")); form.add(startF);
        form.add(darkLabel("End:"));   form.add(endF);

        JTextArea area = new JTextArea();
        area.setEditable(false);
        area.setBackground(CARD_BG);
        area.setForeground(TEXT_WHITE);
        area.setFont(new Font("SansSerif", Font.PLAIN, 12));
        area.setCaretColor(TEXT_WHITE);
        JScrollPane sp = new JScrollPane(area);
        sp.setBorder(BorderFactory.createEmptyBorder());

        JButton search = makeBtn("Search", ACCENT_BLUE, ev -> {
            DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm");
            LocalDateTime start = null, end = null;
            try {
                String st = startF.getText().trim();
                if (!st.isEmpty() && !st.equals("yyyy-MM-ddTHH:mm"))
                    start = LocalDateTime.parse(st, fmt);
                String en = endF.getText().trim();
                if (!en.isEmpty() && !en.equals("yyyy-MM-ddTHH:mm"))
                    end = LocalDateTime.parse(en, fmt);
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(dlg, "Invalid date format. Use yyyy-MM-ddTHH:mm", "Error", JOptionPane.ERROR_MESSAGE);
                return;
            }
            String result = farm.browseSensorReadingHistory(zoneCode, sensorCode, start, end);
            area.setText(result);
        });

        JPanel top = new JPanel(new BorderLayout(6, 0));
        top.setOpaque(false);
        top.add(form, BorderLayout.CENTER);
        top.add(search, BorderLayout.EAST);

        dlg.add(top, BorderLayout.NORTH);
        dlg.add(sp, BorderLayout.CENTER);
        dlg.setVisible(true);
    }

    // ═══════════════════════════ REFRESH ═══════════════════════════

    public void refreshAll() {
        refreshTable();
        refreshStats();
        refreshZoneCombo();
        refreshDashboard();
    }

    private void refreshTable() {
        sensorTableModel.setRowCount(0);
        rowMeta.clear();
        for (Zone zone : farm.getZones()) {
            for (Sensor s : zone.getSensors()) {
                String lastVal = s.getLastReadingValue()
                        .map(v -> String.format("%.2f", v))
                        .orElse("No reading yet");
                sensorTableModel.addRow(new Object[]{
                        s.getUniqueCode(), zone.getCode(),
                        s.getClass().getSimpleName(), s.getUnitOfMeasurement(),
                        s.getMinThreshold(), s.getMaxThreshold(),
                        lastVal, s.getStatus().name()
                });
                rowMeta.add(new String[]{zone.getCode(), s.getUniqueCode()});
            }
        }
    }

    private void refreshStats() {
        int total = 0, active = 0, faulty = 0;
        for (Zone z : farm.getZones()) {
            for (Sensor s : z.getSensors()) {
                total++;
                if (s.getStatus() == SensorStatus.ACTIVE) active++;
                else faulty++;
            }
        }
        totalLabel.setText(String.valueOf(total));
        activeLabel.setText(String.valueOf(active));
        faultyLabel.setText(String.valueOf(faulty));
    }

    private void refreshZoneCombo() {
        zoneDashCombo.removeAllItems();
        zoneCodesList.clear();
        for (Zone z : farm.getZones()) {
            zoneDashCombo.addItem(z.getName() + " (" + z.getCode() + ")");
            zoneCodesList.add(z.getCode());
        }
    }

    private void refreshDashboard() {
        dashboardCards.removeAll();
        int idx = zoneDashCombo.getSelectedIndex();
        if (idx < 0 || idx >= zoneCodesList.size()) { dashboardCards.revalidate(); dashboardCards.repaint(); return; }
        String zc = zoneCodesList.get(idx);
        Optional<Zone> zOpt = farm.getZoneByCode(zc);
        if (zOpt.isEmpty()) return;

        for (Sensor s : zOpt.get().getSensors()) {
            Color tint = CARD_BG;
            Optional<Double> lastVal = s.getLastReadingValue();
            String valText = "No reading yet";
            if (lastVal.isPresent()) {
                double v = lastVal.get();
                valText = String.format("%.2f %s", v, s.getUnitOfMeasurement());
                Object[] st = s.getReadingStatus(v);
                String level = (String) st[1];
                if ("Critical".equals(level)) tint = RED_TINT;
                else if ("Warning".equals(level)) tint = AMBER_TINT;
                else tint = GREEN_TINT;
            }

            RoundedPanel card = new RoundedPanel(tint, 14);
            card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
            card.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));

            JLabel code = new JLabel(s.getUniqueCode());
            code.setFont(new Font("SansSerif", Font.BOLD, 12));
            code.setForeground(TEXT_WHITE);
            code.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel val = new JLabel(valText);
            val.setFont(new Font("SansSerif", Font.PLAIN, 11));
            val.setForeground(TEXT_GRAY);
            val.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel badge = new JLabel(s.getStatus().name());
            badge.setFont(new Font("SansSerif", Font.BOLD, 10));
            badge.setOpaque(true);
            badge.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
            badge.setAlignmentX(Component.LEFT_ALIGNMENT);
            switch (s.getStatus()) {
                case ACTIVE:    badge.setForeground(ACCENT_GREEN); badge.setBackground(new Color(0x00,0x3D,0x20)); break;
                case SUSPENDED: badge.setForeground(ACCENT_AMBER); badge.setBackground(new Color(0x4E,0x39,0x00)); break;
                case FAULTY:    badge.setForeground(ACCENT_RED);   badge.setBackground(new Color(0x4A,0x0E,0x0A)); break;
            }

            card.add(code); card.add(Box.createVerticalStrut(4));
            card.add(val);  card.add(Box.createVerticalStrut(4));
            card.add(badge);
            dashboardCards.add(card);
        }
        dashboardCards.revalidate();
        dashboardCards.repaint();
    }

    // ═══════════════════════════ HELPERS ═══════════════════════════

    private void styleTable(JTable table) {
        table.setBackground(CARD_BG);
        table.setForeground(TEXT_WHITE);
        table.setGridColor(new Color(0x1A, 0x33, 0x50));
        table.setRowHeight(32);
        table.setFont(new Font("SansSerif", Font.PLAIN, 12));
        table.setSelectionBackground(ACCENT_BLUE);
        table.setSelectionForeground(TEXT_WHITE);
        table.setShowGrid(true);
        table.setIntercellSpacing(new Dimension(1, 1));

        JTableHeader header = table.getTableHeader();
        header.setBackground(ACCENT_BLUE);
        header.setForeground(TEXT_WHITE);
        header.setFont(new Font("SansSerif", Font.BOLD, 12));
        header.setReorderingAllowed(false);

        table.setDefaultRenderer(Object.class, new DefaultTableCellRenderer() {
            @Override
            public Component getTableCellRendererComponent(JTable t, Object v,
                                                           boolean sel, boolean foc, int r, int c) {
                Component comp = super.getTableCellRendererComponent(t, v, sel, foc, r, c);
                if (!sel) {
                    comp.setBackground(r % 2 == 0 ? CARD_BG : CARD_BG_ALT);
                    comp.setForeground(TEXT_WHITE);
                }
                return comp;
            }
        });
    }

    private JButton makeBtn(String text, Color bg, ActionListener action) {
        JButton btn = new JButton(text);
        btn.setBackground(bg);
        btn.setForeground(TEXT_WHITE);
        btn.setFont(new Font("SansSerif", Font.BOLD, 12));
        btn.setFocusPainted(false);
        btn.setBorder(BorderFactory.createEmptyBorder(8, 18, 8, 18));
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) { btn.setBackground(bg.brighter()); }
            @Override public void mouseExited(MouseEvent e)  { btn.setBackground(bg); }
        });
        if (action != null) btn.addActionListener(action);
        return btn;
    }

    private JDialog darkDialog(String title, int w, int h) {
        JDialog dlg = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), title, true);
        dlg.setSize(w, h);
        dlg.setLocationRelativeTo(this);
        dlg.getContentPane().setBackground(BG_DARK);
        dlg.setLayout(new BorderLayout(10, 10));
        ((JPanel) dlg.getContentPane()).setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        return dlg;
    }

    private JLabel darkLabel(String text) {
        JLabel l = new JLabel(text);
        l.setForeground(TEXT_GRAY);
        l.setFont(new Font("SansSerif", Font.PLAIN, 12));
        return l;
    }

    private JTextField darkField(String text) {
        JTextField f = new JTextField(text);
        f.setBackground(CARD_BG_ALT);
        f.setForeground(TEXT_WHITE);
        f.setCaretColor(TEXT_WHITE);
        f.setFont(new Font("SansSerif", Font.PLAIN, 12));
        f.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ACCENT_BLUE, 1),
                BorderFactory.createEmptyBorder(4, 6, 4, 6)));
        return f;
    }

    private JPanel wrapButton(JButton btn) {
        JPanel p = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        p.setOpaque(false);
        p.add(btn);
        return p;
    }

    private void warn(String msg) {
        JOptionPane.showMessageDialog(this, msg, "Warning", JOptionPane.WARNING_MESSAGE);
    }
}

package com.farm.demo.view;

import com.farm.demo.model.*;
import com.farm.demo.controller.ZonesController;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.control.*;
import javafx.scene.layout.*;

/**
 * JavaFX view for sensor management.
 * Displays all sensors across zones in a table with their status and readings.
 */
public class SensorsView extends VBox {
    private static final String STYLE_DARK = "-fx-base: #0a1628; -fx-control-inner-background: #0d2137;";

    public SensorsView() {
        setStyle(STYLE_DARK);
        setPadding(new Insets(15));
        setSpacing(10);
        setFillWidth(true);

        // Title
        Label title = new Label("Sensor Management");
        title.setStyle("-fx-font-size: 18; -fx-font-weight: bold; -fx-text-fill: white;");
        getChildren().add(title);

        // Stats bar
        HBox statsBar = buildStatsBar();
        getChildren().add(statsBar);

        // Sensors table
        TableView<SensorRow> table = buildSensorsTable();
        VBox.setVgrow(table, Priority.ALWAYS);
        getChildren().add(table);

        // Action buttons
        HBox actionBar = buildActionBar(table);
        getChildren().add(actionBar);
    }

    private HBox buildStatsBar() {
        HBox bar = new HBox(12);
        bar.setPrefHeight(80);
        bar.setStyle("-fx-fill: transparent;");

        // Try to load farm from model context
        bar.getChildren().addAll(
                makeStatCard("—", "Total Sensors"),
                makeStatCard("—", "Active"),
                makeStatCard("—", "Faulty/Suspended")
        );

        return bar;
    }

    private VBox makeStatCard(String value, String label) {
        VBox card = new VBox(8);
        card.setPadding(new Insets(12));
        card.setStyle("-fx-border-color: #0d2137; -fx-border-radius: 8; -fx-background-color: #0d2137; -fx-background-radius: 8;");
        card.setPrefWidth(150);

        Label valLabel = new Label(value);
        valLabel.setStyle("-fx-font-size: 24; -fx-font-weight: bold; -fx-text-fill: white;");
        Label lblLabel = new Label(label);
        lblLabel.setStyle("-fx-font-size: 12; -fx-text-fill: #99aabb;");
        lblLabel.setWrapText(true);

        card.getChildren().addAll(valLabel, lblLabel);
        card.setAlignment(Pos.CENTER);
        return card;
    }

    private TableView<SensorRow> buildSensorsTable() {
        TableView<SensorRow> table = new TableView<>();
        table.setStyle("-fx-control-inner-background: #0d2137; -fx-table-cell-border-color: #1a3350;");

        TableColumn<SensorRow, String> codeCol = new TableColumn<>("Sensor Code");
        codeCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().code));

        TableColumn<SensorRow, String> zoneCol = new TableColumn<>("Zone");
        zoneCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().zone));

        TableColumn<SensorRow, String> typeCol = new TableColumn<>("Type");
        typeCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().type));

        TableColumn<SensorRow, String> statusCol = new TableColumn<>("Status");
        statusCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().status));

        TableColumn<SensorRow, String> lastReadCol = new TableColumn<>("Last Value");
        lastReadCol.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(c.getValue().lastReading));

        table.getColumns().addAll(codeCol, zoneCol, typeCol, statusCol, lastReadCol);

        // Populate from ZonesController sample data
        try {
            ZonesController controller = new ZonesController();
            for (Zone zone : controller.getAllZones()) {
                for (Sensor s : zone.getSensors()) {
                    String lastVal = s.getLastReadingValue()
                            .map(v -> String.format("%.2f %s", v, s.getUnitOfMeasurement()))
                            .orElse("No reading");
                    table.getItems().add(new SensorRow(
                            s.getUniqueCode(),
                            zone.getCode(),
                            s.getClass().getSimpleName(),
                            s.getStatus().name(),
                            lastVal
                    ));
                }
            }
        } catch (Exception e) {
            // Sample data might not be available
        }

        return table;
    }

    private HBox buildActionBar(TableView<SensorRow> table) {
        HBox bar = new HBox(8);
        bar.setPadding(new Insets(6));
        bar.setStyle("-fx-background-color: #0d2137;");
        bar.setAlignment(Pos.CENTER);

        Button suspendBtn = new Button("Suspend");
        suspendBtn.setStyle("-fx-padding: 8 18; -fx-font-size: 12; -fx-font-weight: bold; -fx-text-fill: white; -fx-background-color: #ffc107; -fx-background-radius: 4;");
        suspendBtn.setOnAction(e -> showAlert("Selected sensor suspended (demo action)", javafx.scene.control.Alert.AlertType.INFORMATION));

        Button reactBtn = new Button("Reactivate");
        reactBtn.setStyle("-fx-padding: 8 18; -fx-font-size: 12; -fx-font-weight: bold; -fx-text-fill: white; -fx-background-color: #00e676; -fx-background-radius: 4;");
        reactBtn.setOnAction(e -> showAlert("Selected sensor reactivated (demo action)", javafx.scene.control.Alert.AlertType.INFORMATION));

        Button faultyBtn = new Button("Mark Faulty");
        faultyBtn.setStyle("-fx-padding: 8 18; -fx-font-size: 12; -fx-font-weight: bold; -fx-text-fill: white; -fx-background-color: #f44336; -fx-background-radius: 4;");
        faultyBtn.setOnAction(e -> showAlert("Selected sensor marked faulty (demo action)", javafx.scene.control.Alert.AlertType.INFORMATION));

        bar.getChildren().addAll(suspendBtn, reactBtn, faultyBtn);
        return bar;
    }

    private void showAlert(String msg, javafx.scene.control.Alert.AlertType type) {
        javafx.scene.control.Alert alert = new javafx.scene.control.Alert(type);
        alert.setTitle("Action");
        alert.setHeaderText(null);
        alert.setContentText(msg);
        alert.showAndWait();
    }

    // Helper class for table data
    public static class SensorRow {
        public String code, zone, type, status, lastReading;
        public SensorRow(String code, String zone, String type, String status, String lastReading) {
            this.code = code;
            this.zone = zone;
            this.type = type;
            this.status = status;
            this.lastReading = lastReading;
        }
    }
}

package com.farm.demo.view;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;

/**
 * Main application window for the Smart Farm GUI.
 * Uses a left sidebar navigation and a CardLayout content area.
 */
public class SmartFarmGUI extends JFrame {

    private static final Color BG_DARK     = new Color(0x0A, 0x16, 0x28);
    private static final Color SIDEBAR_BG  = new Color(0x07, 0x10, 0x1E);
    private static final Color ACCENT_BLUE = new Color(0x15, 0x65, 0xC0);
    private static final Color HOVER_BG    = new Color(0x0D, 0x21, 0x37);
    private static final Color TEXT_WHITE   = Color.WHITE;
    private static final Color TEXT_GRAY    = new Color(0x77, 0x88, 0x99);

    private final CardLayout cardLayout = new CardLayout();
    private final JPanel contentPanel = new JPanel(cardLayout);
    private JButton activeSidebarBtn = null;

    public SmartFarmGUI(Farm farm) {
        setTitle("Smart Farm — Management Dashboard");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(1280, 780);
        setMinimumSize(new Dimension(1000, 600));
        setLocationRelativeTo(null);
        getContentPane().setBackground(BG_DARK);
        setLayout(new BorderLayout());

        // ── Sidebar ──
        JPanel sidebar = new JPanel();
        sidebar.setLayout(new BoxLayout(sidebar, BoxLayout.Y_AXIS));
        sidebar.setBackground(SIDEBAR_BG);
        sidebar.setPreferredSize(new Dimension(200, 0));
        sidebar.setBorder(BorderFactory.createEmptyBorder(10, 0, 10, 0));

        // Logo / title area
        JLabel logo = new JLabel("  \uD83C\uDF3E Smart Farm", SwingConstants.LEFT);
        logo.setFont(new Font("SansSerif", Font.BOLD, 18));
        logo.setForeground(TEXT_WHITE);
        logo.setAlignmentX(Component.LEFT_ALIGNMENT);
        logo.setBorder(BorderFactory.createEmptyBorder(14, 16, 20, 10));
        logo.setMaximumSize(new Dimension(Integer.MAX_VALUE, 60));
        sidebar.add(logo);

        // Separator
        JSeparator sep = new JSeparator();
        sep.setForeground(new Color(0x1A, 0x33, 0x50));
        sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        sidebar.add(sep);
        sidebar.add(Box.createVerticalStrut(10));

        // Navigation buttons
        JButton sensorsBtn = makeSidebarButton("\uD83D\uDCE1  Sensors", "sensors");
        JButton alertsBtn  = makeSidebarButton("\u26A0\uFE0F  Alerts",  "alerts");

        sidebar.add(sensorsBtn);
        sidebar.add(Box.createVerticalStrut(4));
        sidebar.add(alertsBtn);
        sidebar.add(Box.createVerticalGlue());

        // Version label at bottom
        JLabel version = new JLabel("  v1.0.0");
        version.setFont(new Font("SansSerif", Font.PLAIN, 10));
        version.setForeground(TEXT_GRAY);
        version.setAlignmentX(Component.LEFT_ALIGNMENT);
        version.setBorder(BorderFactory.createEmptyBorder(0, 16, 8, 0));
        sidebar.add(version);

        add(sidebar, BorderLayout.WEST);

        // ── Content area ──
        contentPanel.setBackground(BG_DARK);

        // Welcome panel
        JPanel welcome = new JPanel(new GridBagLayout());
        welcome.setBackground(BG_DARK);
        JLabel wLabel = new JLabel("Select a panel from the sidebar");
        wLabel.setFont(new Font("SansSerif", Font.PLAIN, 16));
        wLabel.setForeground(TEXT_GRAY);
        welcome.add(wLabel);

        SensorManagementPanel sensorPanel = new SensorManagementPanel(farm);
        AlertManagementPanel  alertPanel  = new AlertManagementPanel(farm);

        contentPanel.add(welcome,     "welcome");
        contentPanel.add(sensorPanel, "sensors");
        contentPanel.add(alertPanel,  "alerts");

        add(contentPanel, BorderLayout.CENTER);

        // Select sensors by default
        cardLayout.show(contentPanel, "sensors");
        setActiveButton(sensorsBtn);
    }

    private JButton makeSidebarButton(String text, String cardName) {
        JButton btn = new JButton(text);
        btn.setFont(new Font("SansSerif", Font.BOLD, 13));
        btn.setForeground(TEXT_GRAY);
        btn.setBackground(SIDEBAR_BG);
        btn.setHorizontalAlignment(SwingConstants.LEFT);
        btn.setFocusPainted(false);
        btn.setBorderPainted(false);
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.setAlignmentX(Component.LEFT_ALIGNMENT);
        btn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 42));
        btn.setBorder(BorderFactory.createEmptyBorder(10, 20, 10, 10));

        btn.addMouseListener(new MouseAdapter() {
            @Override public void mouseEntered(MouseEvent e) {
                if (btn != activeSidebarBtn) btn.setBackground(HOVER_BG);
            }
            @Override public void mouseExited(MouseEvent e) {
                if (btn != activeSidebarBtn) btn.setBackground(SIDEBAR_BG);
            }
        });

        btn.addActionListener(e -> {
            cardLayout.show(contentPanel, cardName);
            setActiveButton(btn);
        });

        return btn;
    }

    private void setActiveButton(JButton btn) {
        if (activeSidebarBtn != null) {
            activeSidebarBtn.setBackground(SIDEBAR_BG);
            activeSidebarBtn.setForeground(TEXT_GRAY);
        }
        activeSidebarBtn = btn;
        btn.setBackground(ACCENT_BLUE);
        btn.setForeground(TEXT_WHITE);
    }

    // ═══════════════════════════ MAIN ═══════════════════════════

    public static void main(String[] args) {
        // Set up a demo farm with sample data
        try {
            Farm farm = new Farm("FARM-001", "ESI Green Valley");

            CropZone cropZone = new CropZone("CZ-01", "North Crop Field");
            LivestockZone livestockZone = new LivestockZone("LZ-01", "East Livestock Area");
            AquacultureZone aquaZone = new AquacultureZone("AZ-01", "South Aquaculture Tank");

            farm.addZone(cropZone);
            farm.addZone(livestockZone);
            farm.addZone(aquaZone);

            TemperatureSensor tempSensor = new TemperatureSensor("TEMP-CZ01", "CZ-01", 10.0, 35.0, "°C");
            HumiditySensor humiditySensor = new HumiditySensor("HUMI-CZ01", "CZ-01", 30.0, 80.0, "%");
            SoilSensor soilSensor = new SoilSensor("SOIL-CZ01", "CZ-01", 5.5, 7.5, "pH");
            BiometricSensor bioSensor = new BiometricSensor("BIO-LZ01", "LZ-01", 36.0, 39.5, "°C");
            GPSCollarSensor gpsSensor = new GPSCollarSensor("GPS-LZ01", "LZ-01", 33.0, 35.0, 2.0, 4.0, "°");
            WaterTemperatureSensor waterTempSensor = new WaterTemperatureSensor("WTEMP-AZ01", "AZ-01", 18.0, 28.0, "°C");
            DissolvedOxygenSensor dissolvedOxygenSensor = new DissolvedOxygenSensor("DOX-AZ01", "AZ-01", 6.0, 12.0, "mg/L");

            cropZone.addSensor(tempSensor);
            cropZone.addSensor(humiditySensor);
            cropZone.addSensor(soilSensor);
            livestockZone.addSensor(bioSensor);
            livestockZone.addSensor(gpsSensor);
            aquaZone.addSensor(waterTempSensor);
            aquaZone.addSensor(dissolvedOxygenSensor);

            // Add some readings to generate alerts
            tempSensor.addReading(22.0);
            humiditySensor.addReading(55.0);
            soilSensor.addReading(6.5);
            bioSensor.addReading(38.0);
            waterTempSensor.addReading(23.0);
            dissolvedOxygenSensor.addReading(8.0);
            gpsSensor.addGPSReading(34.0, 3.0);

            // Warning readings
            tempSensor.addReading(38.0);
            humiditySensor.addReading(25.0);

            // Critical readings
            bioSensor.addReading(50.0);
            waterTempSensor.addReading(5.0);
            dissolvedOxygenSensor.addReading(0.5);
            gpsSensor.addGPSReading(10.0, 20.0);

            SwingUtilities.invokeLater(() -> {
                SmartFarmGUI gui = new SmartFarmGUI(farm);
                gui.setVisible(true);
            });

        } catch (ThresholdException e) {
            e.printStackTrace();
        }
    }
}

